app/components/history/revision-picker.t.source:
// The revisions of one item, newest first: each opens its source, and any two can be picked and
// compared. A plain GET form, so it works as delivered: the picks travel as `v` in the address and
// the history page orders them. Read-only: nothing here changes the site.

import { Link } from "react-router";
import { Button } from "capsomer/react/button";
import { Pill } from "capsomer/react/status";
import { Time } from "capsomer/react/time";

export type RevisionRow = { version: string; at: string; author: string; message: string };

const utc = (iso: string) => `${iso.slice(0, 16).replace("T", " ")} UTC`;

export function RevisionPicker({ revisions, historyPath, picked = [], label }: { revisions: RevisionRow[]; historyPath: string; picked?: string[]; label: string }) {
  const captionId = `${label.replace(/\W+/g, "-").toLowerCase()}-caption`;
  return (
    <form method="get" action={historyPath} className="app-stack" data-tight aria-label={label}>
      <div className="cap-table-wrap" role="region" aria-labelledby={captionId} tabIndex={0}>
        <table className="cap-table">
          <caption id={captionId} className="cap-sr-only">
            {label}, newest first
          </caption>
          <thead>
            <tr>
              <th scope="col">Compare</th>
              <th scope="col">Revision</th>
              <th scope="col">By</th>
              <th scope="col">Saved</th>
            </tr>
          </thead>
          <tbody>
            {revisions.map((r, i) => (
              <tr key={r.version} data-state={picked.includes(r.version) ? "selected" : undefined}>
                <td>
                  <label className="cap-check">
                    <input type="checkbox" name="v" value={r.version} defaultChecked={picked.includes(r.version)} />
                    <span className="cap-sr-only">
                      Compare the revision from {utc(r.at)} by {r.author}
                    </span>
                  </label>
                </td>
                <th scope="row">
                  <Link className="cap-table-open" to={`${historyPath}?version=${encodeURIComponent(r.version)}`}>
                    {r.message || "No message"}
                    <span className="cap-sr-only">, open its source</span>
                  </Link>
                  {i === 0 ? <Pill tone="ok">Current</Pill> : null}
                </th>
                <td>{r.author}</td>
                <td>
                  <Time at={r.at} />
                  <span className="cap-table-aside">{utc(r.at)}</span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="app-actions">
        <Button type="submit" variant="primary">
          Compare the two picked
        </Button>
        <span className="cap-muted">Pick two revisions. The older is shown first.</span>
      </div>
    </form>
  );
}

app/lib/content.server.ts.source:
// Every read and write of a site's content that Carrel performs for a person: autosave to D1, and
// the writes it sends through site-api. Roles are checked here, not only in the route, so every
// door (the UI now, MCP tools in stage 5) is held to the same rule.

import type { ContentDoc } from "@dustinedwards/site-api";
import { SiteApiError } from "@dustinedwards/site-api/client";
import { and, eq } from "drizzle-orm";
import { drizzle } from "drizzle-orm/d1";

import { changes, drafts } from "~/db/schema";
import { indexDoc, removeFromIndex } from "~/lib/index.server";
import { checkLegalWrite } from "~/lib/legal.server";
import type { Viewer } from "~/lib/people.server";
import type { SiteProject } from "~/lib/projects.server";
import { can, type Action, type Role } from "~/lib/roles";
import { siteClient, siteConnection } from "~/lib/sites.server";
import { recordPublication, summaryFrom } from "~/lib/social/queue.server";

export type Draft = { source: string; baseVersion: string | null; updatedAt: string };

export type WriteAction = "save" | "publish" | "schedule" | "unpublish";

export type WriteOutcome =
  | { ok: true; action: WriteAction; version: string; status: ContentDoc["status"]; changeId: string }
  | { ok: false; reason: "conflict"; currentVersion: string | null; message: string }
  | { ok: false; reason: "refused" | "failed"; message: string };

function forbid(): never {
  throw new Response("Forbidden", { status: 403 });
}

/** Enough of a project to check a role on it: a site or a book. Drafts are keyed by project and item either way. */
export type ProjectRole = { id: number; role: Role };

function requireCan(project: { role: Role }, action: Action) {
  if (!can(project.role, action)) forbid();
}

/** A 404 from the site means the item is not there yet, which is how a new post starts. */
export async function readDoc(env: Env, project: SiteProject, itemId: string, fetcher?: typeof fetch) {
  requireCan(project, "read");
  try {
    return await siteClient(env, project.site, fetcher).get(itemId);
  } catch (error) {
    if (error instanceof SiteApiError && error.status === 404) return null;
    throw error;
  }
}

export async function readDraft(db: D1Database, project: ProjectRole, viewer: Viewer, itemId: string) {
  requireCan(project, "read");
  const row = await drizzle(db)
    .select({ source: drafts.source, baseVersion: drafts.baseVersion, updatedAt: drafts.updatedAt })
    .from(drafts)
    .where(and(eq(drafts.projectId, project.id), eq(drafts.itemId, itemId), eq(drafts.personId, viewer.id)))
    .get();
  return row ?? null;
}

/** The working copy is private to the person: an Editor may autosave a live post, never send it. The same for a book's files. */
export async function autosave(
  db: D1Database,
  project: ProjectRole,
  viewer: Viewer,
  itemId: string,
  input: { source: string; baseVersion: string | null },
  now = new Date(),
): Promise<Draft> {
  requireCan(project, "edit");
  const updatedAt = now.toISOString();
  await drizzle(db)
    .insert(drafts)
    .values({ projectId: project.id, itemId, personId: viewer.id, source: input.source, baseVersion: input.baseVersion, updatedAt })
    .onConflictDoUpdate({
      target: [drafts.projectId, drafts.itemId, drafts.personId],
      set: { source: input.source, baseVersion: input.baseVersion, updatedAt },
    });
  return { source: input.source, baseVersion: input.baseVersion, updatedAt };
}

export async function discardDraft(db: D1Database, project: ProjectRole, viewer: Viewer, itemId: string) {
  requireCan(project, "edit");
  await drizzle(db)
    .delete(drafts)
    .where(and(eq(drafts.projectId, project.id), eq(drafts.itemId, itemId), eq(drafts.personId, viewer.id)));
}

/**
 * What a write needs. Saving changes to a published or scheduled item changes the public site, so it
 * is a publish, not an edit: an Editor may save drafts only.
 */
export function actionNeeded(action: WriteAction, current: ContentDoc | null): Action {
  if (action !== "save") return "publish";
  return current && current.status !== "draft" ? "publish" : "edit";
}

export async function writeToSite(
  env: Env,
  project: SiteProject,
  viewer: Viewer,
  itemId: string,
  request:
    | { action: "save"; source: string; expectedVersion: string | null }
    | { action: "publish"; expectedVersion: string; source?: string }
    | { action: "schedule"; expectedVersion: string; publishAt: string; source?: string }
    | { action: "unpublish"; expectedVersion: string },
  fetcher?: typeof fetch,
  /** The AI client, when the write came through the AI door; the authorship record credits it. */
  opts: { client?: string } = {},
): Promise<WriteOutcome> {
  // Checked twice: before any request, from the role alone, and again against the item's live state.
  requireCan(project, request.action === "save" ? "edit" : "publish");
  const client = siteClient(env, project.site, fetcher);
  const current = await readDoc(env, project, itemId, fetcher);
  requireCan(project, actionNeeded(request.action, current));

  // A legal page has its shared sections written in and its date stamped; a page the site keeps public is not taken down.
  const legal = await checkLegalWrite(env.DB, project, itemId, request, current, new Date());
  if (!legal.ok) return { ok: false, reason: "refused", message: legal.message };
  if ("source" in request && request.source !== undefined) request = { ...request, source: legal.source };

  const changeId = crypto.randomUUID();
  let result;
  try {
    switch (request.action) {
      case "save":
        result = await client.saveDraft(itemId, { source: request.source, expectedVersion: request.expectedVersion, changeId });
        break;
      case "publish":
        result = await client.publish(itemId, { expectedVersion: request.expectedVersion, changeId, source: request.source });
        break;
      case "schedule":
        result = await client.schedule(itemId, {
          expectedVersion: request.expectedVersion,
          changeId,
          publishAt: request.publishAt,
          source: request.source,
        });
        break;
      case "unpublish":
        result = await client.unpublish(itemId, { expectedVersion: request.expectedVersion, changeId });
        break;
    }
  } catch (error) {
    if (error instanceof SiteApiError && error.body?.error === "version-conflict") {
      return {
        ok: false,
        reason: "conflict",
        currentVersion: error.body.currentVersion ?? null,
        message: "The post changed on the site since you opened it. Your text is kept here; reload the site's version to compare before saving.",
      };
    }
    // The site's own words for a refusal, a text it cannot take or a write it does not do for this kind.
    if (error instanceof SiteApiError && error.body && ["refused", "invalid", "not-implemented"].includes(error.body.error)) {
      return { ok: false, reason: "refused", message: error.body.message };
    }
    console.error(JSON.stringify({ write: "failed", itemId, action: request.action, error: String(error) }));
    return { ok: false, reason: "failed", message: "The site did not accept the write. Your text is kept here." };
  }

  await drizzle(env.DB).insert(changes).values({
    id: changeId,
    projectId: project.id,
    itemId,
    personId: viewer.id,
    action: request.action,
    versionBefore: current?.version ?? null,
    versionAfter: result.version,
    client: opts.client ?? null,
  });

  // The draft is done once its text reached the site; an unpublish sends no text, so it stays.
  if ("source" in request && request.source !== undefined) {
    await drizzle(env.DB)
      .delete(drafts)
      .where(and(eq(drafts.projectId, project.id), eq(drafts.itemId, itemId), eq(drafts.personId, viewer.id)));
  }

  // The write landed; a failed re-read only leaves the index to the next refresh.
  try {
    const doc = await client.get(itemId);
    await indexDoc(env.DB, project.id, doc);
    // A piece going live is the one event social posts may announce (design decision 5).
    if (request.action === "publish" && doc.status === "published") {
      const connection = siteConnection(env, project.site);
      const url = connection.state === "connected" && doc.path ? new URL(doc.path, connection.origin).href : "";
      await recordPublication(env.DB, project.id, { id: itemId, title: doc.title, url, summary: summaryFrom(doc.source) });
    }
  } catch (error) {
    console.error(JSON.stringify({ index: "after-write-failed", itemId, error: String(error) }));
  }

  return { ok: true, action: request.action, version: result.version, status: result.status, changeId };
}

export type DeleteOutcome =
  | { ok: true; changeId: string; version: string; title: string; recorded: boolean }
  | { ok: false; reason: "missing" | "conflict" | "refused" | "not-implemented" | "failed"; message: string };

/**
 * Whether the site can delete a post, from its meta. A site on an older site API, or one whose adapter
 * has no delete, says no and the reason is plain; a site that does not answer says that.
 */
export async function contentDeleteOffered(
  env: Env,
  project: SiteProject,
  fetcher?: typeof fetch,
): Promise<{ offered: true } | { offered: false; reason: string }> {
  requireCan(project, "read");
  try {
    const meta = await siteClient(env, project.site, fetcher).meta();
    return meta.capabilities.contentDelete === true ? { offered: true } : { offered: false, reason: "The site does not delete posts through Carrel yet." };
  } catch (error) {
    console.error(JSON.stringify({ meta: "failed", error: String(error) }));
    return { offered: false, reason: "The site did not answer, so Carrel cannot tell whether it deletes posts." };
  }
}

/**
 * Deletes one post from the site. Owner only, checked before the site is asked anything. The version
 * sent is the one the site holds now, so a post that changed between reading it and this call is
 * refused as stale and stays. The authorship record is written only for a delete the site carried out;
 * the person's own working drafts of the post stay in Carrel.
 */
export async function deleteFromSite(
  env: Env,
  project: SiteProject,
  viewer: Viewer,
  itemId: string,
  fetcher?: typeof fetch,
  opts: { client?: string } = {},
): Promise<DeleteOutcome> {
  requireCan(project, "delete_content");
  const client = siteClient(env, project.site, fetcher);
  const current = await readDoc(env, project, itemId, fetcher);
  if (!current) {
    await removeFromIndex(env.DB, project.id, itemId);
    return { ok: false, reason: "missing", message: "The site has no post with this id, so there is nothing to delete." };
  }

  const changeId = crypto.randomUUID();
  try {
    await client.delete(itemId, { expectedVersion: current.version, changeId });
  } catch (error) {
    if (error instanceof SiteApiError) {
      if (error.status === 501) return { ok: false, reason: "not-implemented", message: "The site does not delete posts through Carrel yet." };
      if (error.body?.error === "version-conflict") {
        return { ok: false, reason: "conflict", message: "The post changed on the site while this ran. It was not deleted; open it to see the new version." };
      }
      if (error.status === 404) {
        await removeFromIndex(env.DB, project.id, itemId);
        return { ok: false, reason: "missing", message: "The post was already gone from the site." };
      }
      if (error.body?.error === "refused") return { ok: false, reason: "refused", message: error.body.message };
    }
    console.error(JSON.stringify({ write: "failed", itemId, action: "content-delete", error: String(error) }));
    return { ok: false, reason: "failed", message: "The site did not accept the delete. The post is still there." };
  }

  await removeFromIndex(env.DB, project.id, itemId);
  // The site has deleted the post. If the record cannot be written, say so rather than report a
  // clean success: the screen shows the post as deleted and the record as missing.
  let recorded = true;
  try {
    await drizzle(env.DB).insert(changes).values({
      id: changeId,
      projectId: project.id,
      itemId,
      personId: viewer.id,
      action: "content-delete",
      versionBefore: current.version,
      versionAfter: null,
      client: opts.client ?? null,
    });
  } catch (error) {
    recorded = false;
    console.error(JSON.stringify({ record: "failed", itemId, action: "content-delete", changeId, error: String(error) }));
  }
  return { ok: true, changeId, version: current.version, title: current.title, recorded };
}

app/lib/legal.ts.source:
// Legal pages: a privacy or terms page is an ordinary page on the site, with a few fields in its
// frontmatter and shared sections in its body. A shared section is written once in Carrel and
// reused by every site's page; a site's own facts are the fields. Each site still publishes its own
// page, so the shared text reaches a site only when its page is published. Pure, so the server, the
// editor and the tests read it the same way.

import { readFields, setField, splitSource, joinSource } from "~/lib/frontmatter";

export const LEGAL_TYPES = ["privacy", "terms"] as const;
export type LegalType = (typeof LEGAL_TYPES)[number];

/** The id a site gives each legal page; the page's address is registered on the site, never made here. */
export const legalItemId = (type: LegalType) => `page.${type}`;

/** The fields a shared section may name as `{{site_name}}`: the site's own facts. */
export const VARIABLES = ["site_name", "operator_name", "contact", "jurisdiction", "data_held"] as const;
type Variable = (typeof VARIABLES)[number];

export const SECTION_KEY = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

/** Reads the frontmatter's `legal_type`, or null when the source is not a legal page. */
export function legalTypeOf(source: string): LegalType | null {
  const { front } = splitSource(source);
  if (front === null) return null;
  const match = /^legal_type:\s*["']?([a-z]+)["']?\s*$/m.exec(front);
  return LEGAL_TYPES.find((t) => t === match?.[1]) ?? null;
}

/** The `path:` line of a source's frontmatter, or null. */
export function pathOf(source: string): string | null {
  const { front } = splitSource(source);
  const match = front === null ? null : /^path:\s*["']?([^"'\r\n]*?)["']?\s*$/m.exec(front);
  return match ? match[1]! : null;
}

export const marker = (key: string) => `<!-- shared:${key} -->`;

// An opening marker, and the closing one when the section was already expanded.
const BLOCK = /<!--\s*shared:([a-z0-9-]+)\s*-->(?:[\s\S]*?<!--\s*\/shared:\1\s*-->)?/g;
const TOKEN = /\{\{\s*([a-z_]+)\s*\}\}/g;

export type SharedSection = { key: string; title: string; body: string };

export type Expansion = {
  text: string;
  /** Section keys the body names that Carrel does not have. They are left as written. */
  unknownSections: string[];
  /** Fields a used section needs and the page leaves empty. The token stays in the text. */
  missingFields: string[];
};

/** The keys of the shared sections a body names, in order. */
export function sectionsUsed(body: string): string[] {
  return [...body.matchAll(BLOCK)].map((m) => m[1]!);
}

/**
 * The body with each shared section's text written between its markers, the page's own fields
 * filled in. Running it again on its own output changes nothing, so a page can be expanded on every
 * write and compared with what is stored.
 */
export function expandShared(body: string, sections: readonly SharedSection[], values: Partial<Record<Variable, string>>): Expansion {
  const unknownSections: string[] = [];
  const missingFields: string[] = [];
  const text = body.replace(BLOCK, (whole, key: string) => {
    const section = sections.find((s) => s.key === key);
    if (!section) {
      unknownSections.push(key);
      return whole;
    }
    const filled = section.body.replace(TOKEN, (token, name: string) => {
      if (!(VARIABLES as readonly string[]).includes(name)) return token;
      const value = values[name as Variable]?.trim();
      if (value) return value;
      if (!missingFields.includes(name)) missingFields.push(name);
      return token;
    });
    return `${marker(key)}\n${filled.trim()}\n<!-- /shared:${key} -->`;
  });
  return { text, unknownSections, missingFields };
}

/** The page's own facts, from its frontmatter, for the sections that name them. */
export function valuesOf(source: string): Partial<Record<Variable, string>> {
  const fields = readFields(splitSource(source).front);
  return Object.fromEntries(VARIABLES.map((v) => [v, fields[v]]));
}

export type LegalWrite = { ok: true; source: string } | { ok: false; message: string };

/**
 * What goes to the site for a write to a legal page: shared sections expanded, and `last_updated`
 * stamped when the write makes a changed body public. Saving a draft only expands what it can: a
 * missing field is no reason to lose work, but a page that would go public with `{{operator_name}}`
 * still in it, or a section that does not exist, is refused with the field or key named.
 *
 * `public` is true for a publish, and for a save to a page that is already live.
 */
export function prepareLegalWrite(input: { source: string; stored: string | null; storedPublic: boolean; sections: readonly SharedSection[]; public: boolean; today: string }): LegalWrite {
  const parts = splitSource(input.source);
  if (parts.front === null) return { ok: false, message: "A legal page keeps its details in frontmatter, and this text has none." };
  const expansion = expandShared(parts.body, input.sections, valuesOf(input.source));
  if (input.public && expansion.unknownSections.length > 0) {
    return { ok: false, message: `There is no shared section called ${expansion.unknownSections.map((k) => `"${k}"`).join(", ")}. Add it on the Legal tab or remove its marker.` };
  }
  if (input.public && expansion.missingFields.length > 0) {
    return { ok: false, message: `The shared text needs ${expansion.missingFields.join(", ")} filled in on this page before it goes public.` };
  }
  let front = parts.front;
  const storedBody = input.stored === null ? null : splitSource(input.stored).body;
  if (input.public && (storedBody !== expansion.text || !input.storedPublic)) front = setField(front, "last_updated", input.today);
  return { ok: true, source: joinSource({ ...parts, front, body: expansion.text }) };
}

app/lib/novels/repo.server.ts.source:
// The novels repository, reached through the GitHub App `carrel-writer` (design setup step 8),
// installed on that one repository with contents read and write and nothing else. Carrel reads the
// tree and files and commits one file at a time, each with the version it expects to replace.

import { SignJWT } from "jose";

export const NOVELS_REPO = "DrDustinEdwards/novels";
export const NOVELS_BRANCH = "main";
const API = "https://api.github.com";

export type RepoFile = { source: string; sha: string };

/** A write refused because the file is not at the version the writer expected. */
export class GitConflict extends Error {
  constructor(readonly currentSha: string | null) {
    super("version-conflict");
  }
}

export class NovelsNotConnected extends Error {
  constructor(readonly detail: string) {
    super(detail);
  }
}

export interface NovelsRepo {
  /** Every file under `prefix` (a folder, no trailing slash), with its blob sha. */
  tree(prefix: string): Promise<{ path: string; sha: string }[]>;
  read(path: string): Promise<RepoFile | null>;
  /**
   * Commits one file. `expectedSha` null means the file must not exist yet. Throws GitConflict when
   * the file is not at that version.
   */
  write(path: string, input: { source: string; expectedSha: string | null; message: string; author: { name: string; email: string } }): Promise<{ sha: string; commit: string }>;
}

// ---------- the connection

export type NovelsConnection =
  | { state: "connected"; appId: string; privateKey: string }
  | { state: "not-connected" | "misconfigured"; detail: string };

export function novelsConnection(env: Env): NovelsConnection {
  const appId = env.NOVELS_APP_ID?.trim();
  const key = env.NOVELS_APP_PRIVATE_KEY?.trim();
  if (!appId && !key) {
    return { state: "not-connected", detail: "The GitHub App for the novels repository is not set up yet (NOVELS_APP_ID, NOVELS_APP_PRIVATE_KEY)." };
  }
  if (!appId || !/^\d+$/.test(appId)) return { state: "misconfigured", detail: "NOVELS_APP_ID is missing or is not the App's numeric id." };
  if (!key || !/-----BEGIN (RSA )?PRIVATE KEY-----/.test(key)) {
    return { state: "misconfigured", detail: "NOVELS_APP_PRIVATE_KEY is missing or is not a PEM private key." };
  }
  return { state: "connected", appId, privateKey: key };
}

// ---------- GitHub App authentication

function base64ToBytes(b64: string): Uint8Array<ArrayBuffer> {
  const binary = atob(b64.replace(/\s+/g, ""));
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) out[i] = binary.charCodeAt(i);
  return out;
}

function bytesToBase64(bytes: Uint8Array): string {
  let binary = "";
  for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(binary);
}

function derLength(n: number): number[] {
  if (n < 0x80) return [n];
  const bytes: number[] = [];
  for (let v = n; v > 0; v >>= 8) bytes.unshift(v & 0xff);
  return [0x80 | bytes.length, ...bytes];
}

function der(tag: number, content: Uint8Array | number[]): number[] {
  const body = Array.from(content);
  return [tag, ...derLength(body.length), ...body];
}

/**
 * GitHub hands out App keys as PKCS#1 ("BEGIN RSA PRIVATE KEY"); WebCrypto imports PKCS#8 only. The
 * PKCS#8 form is the PKCS#1 key wrapped with the rsaEncryption algorithm id, so Dustin can paste the
 * downloaded file as it is.
 */
export function pkcs8FromPem(pem: string): Uint8Array<ArrayBuffer> {
  const body = pem.replace(/-----(BEGIN|END) [A-Z ]+-----/g, "");
  const bytes = base64ToBytes(body);
  if (!/BEGIN RSA PRIVATE KEY/.test(pem)) return bytes;
  const version = der(0x02, [0x00]);
  // SEQUENCE { OID 1.2.840.113549.1.1.1, NULL }
  const algorithm = der(0x30, [0x06, 0x09, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x01, 0x05, 0x00]);
  return new Uint8Array(der(0x30, [...version, ...algorithm, ...der(0x04, bytes)]));
}

export async function appJwt(appId: string, pem: string, now = Date.now()): Promise<string> {
  const key = await crypto.subtle.importKey("pkcs8", pkcs8FromPem(pem), { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" }, false, ["sign"]);
  const iat = Math.floor(now / 1000) - 60; // GitHub allows for clock drift this way.
  return new SignJWT({}).setProtectedHeader({ alg: "RS256" }).setIssuer(appId).setIssuedAt(iat).setExpirationTime(iat + 540).sign(key);
}

type Fetch = typeof fetch;

function headers(token: string): HeadersInit {
  return {
    Authorization: `Bearer ${token}`,
    Accept: "application/vnd.github+json",
    "X-GitHub-Api-Version": "2022-11-28",
    "User-Agent": "carrel",
  };
}

/** Installation tokens last an hour; one per isolate, renewed five minutes early. */
const tokenCache = new Map<string, { token: string; expires: number }>();

export async function installationToken(appId: string, pem: string, fetcher: Fetch = fetch, now = Date.now()): Promise<string> {
  const cached = tokenCache.get(appId);
  if (cached && cached.expires - 5 * 60_000 > now) return cached.token;
  const jwt = await appJwt(appId, pem, now);
  const inst = await fetcher(`${API}/repos/${NOVELS_REPO}/installation`, { headers: headers(jwt) });
  if (!inst.ok) throw new Error(`GitHub did not find the App's installation on ${NOVELS_REPO} (${inst.status}).`);
  const { id } = (await inst.json()) as { id: number };
  // Narrowed to the one repository and to contents, whatever the installation allows.
  const res = await fetcher(`${API}/app/installations/${id}/access_tokens`, {
    method: "POST",
    headers: headers(jwt),
    body: JSON.stringify({ repositories: [NOVELS_REPO.split("/")[1]], permissions: { contents: "write" } }),
  });
  if (!res.ok) throw new Error(`GitHub refused an installation token (${res.status}).`);
  const body = (await res.json()) as { token: string; expires_at: string };
  tokenCache.set(appId, { token: body.token, expires: Date.parse(body.expires_at) });
  return body.token;
}

export function clearTokenCache(): void {
  tokenCache.clear();
}

// ---------- the GitHub contents client

function encodePath(path: string): string {
  return path.split("/").map(encodeURIComponent).join("/");
}

function utf8ToBase64(text: string): string {
  return bytesToBase64(new TextEncoder().encode(text));
}

function base64ToUtf8(b64: string): string {
  return new TextDecoder().decode(base64ToBytes(b64));
}

export function githubRepo(token: () => Promise<string>, fetcher: Fetch = fetch): NovelsRepo {
  const repoUrl = `${API}/repos/${NOVELS_REPO}`;
  const call = async (url: string, init: RequestInit = {}) => fetcher(url, { ...init, headers: { ...headers(await token()), ...init.headers } });

  const repo: NovelsRepo = {
    async tree(prefix) {
      const res = await call(`${repoUrl}/git/trees/${NOVELS_BRANCH}?recursive=1`);
      if (!res.ok) throw new Error(`GitHub did not list the novels repository (${res.status}).`);
      const body = (await res.json()) as { truncated: boolean; tree: { path: string; type: string; sha: string }[] };
      // A truncated tree would make files look deleted; refuse it rather than index half a book.
      if (body.truncated) throw new Error("GitHub truncated the novels repository's tree; it is too large to list in one call.");
      const start = `${prefix}/`;
      return body.tree.filter((e) => e.type === "blob" && e.path.startsWith(start)).map((e) => ({ path: e.path.slice(start.length), sha: e.sha }));
    },

    async read(path) {
      const res = await call(`${repoUrl}/contents/${encodePath(path)}?ref=${NOVELS_BRANCH}`);
      if (res.status === 404) return null;
      if (!res.ok) throw new Error(`GitHub did not return ${path} (${res.status}).`);
      const body = (await res.json()) as { type: string; content?: string; encoding?: string; sha: string };
      if (body.type !== "file" || body.encoding !== "base64" || body.content === undefined) throw new Error(`${path} is not a file GitHub returns inline.`);
      return { source: base64ToUtf8(body.content), sha: body.sha };
    },

    async write(path, input) {
      const res = await call(`${repoUrl}/contents/${encodePath(path)}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          message: input.message,
          content: utf8ToBase64(input.source),
          branch: NOVELS_BRANCH,
          author: input.author,
          ...(input.expectedSha ? { sha: input.expectedSha } : {}),
        }),
      });
      // 409: the sha is not the file's; 422: a create for a file that exists (no sha supplied).
      if (res.status === 409 || res.status === 422) {
        const current = await repo.read(path);
        // A 422 for a file that is where the writer expected is some other refusal, not a conflict.
        if ((current?.sha ?? null) === input.expectedSha) throw new Error(`GitHub refused the commit to ${path} (${res.status}).`);
        throw new GitConflict(current?.sha ?? null);
      }
      if (!res.ok) throw new Error(`GitHub did not accept the commit to ${path} (${res.status}).`);
      const body = (await res.json()) as { content: { sha: string }; commit: { sha: string } };
      return { sha: body.content.sha, commit: body.commit.sha };
    },
  };
  return repo;
}

/** The repository for this Worker's credentials; throws NovelsNotConnected until the App is set up. */
export function novelsRepo(env: Env, fetcher: Fetch = fetch): NovelsRepo {
  const connection = novelsConnection(env);
  if (connection.state !== "connected") throw new NovelsNotConnected(connection.detail);
  return githubRepo(() => installationToken(connection.appId, connection.privateKey, fetcher), fetcher);
}

