// The AI-habits lint on every post (design section 5, "Social"), and the checks a post needs before
// it can go: it fits the platform, it is not a reply in disguise, it is not empty. A post with any
// finding is held for Dustin; the lint flags and he decides.
//
// The word list is stage 4's (SEED_WORDS, the AI-tells list in capsid/conventions.md): one list for
// books and posts.

import { SEED_WORDS } from "~/lib/novels/checks";

import { graphemes, type Platform } from "./platforms.server";

const NOT_JUST = [
  /(?:\bnot|n['\u2019]t)\s+(?:just|only|merely|simply)\s+[^.!?;:,]{1,60}[,;:]\s*(?:it|this|that|he|she|they|we|you)(?:['\u2019](?:s|re)|\s+(?:is|was|are|were))\b/iu,
  /\b(?:it|this|that)(?:['\u2019]s\s+not|\s+is\s+not|\s+was\s+not|\s+isn['\u2019]t|\s+wasn['\u2019]t)\s+[^.!?;:]{1,50}[.,;:]\s*(?:it|this|that)(?:['\u2019]s|\s+(?:is|was))\b/iu,
];

/** X counts every link as 23 characters, however long; Bluesky counts graphemes. */
function length(text: string, platform: Platform): number {
  if (platform === "bluesky") return graphemes(text);
  return [...text.replace(/https?:\/\/\S+/g, "x".repeat(23))].length;
}

const LIMIT: Record<Platform, number> = { bluesky: 300, x: 280 };

export function lintPost(text: string, platform: Platform): string[] {
  const out: string[] = [];
  const t = text.trim();
  if (!t) return ["The post is empty."];
  const n = length(t, platform);
  if (n > LIMIT[platform]) out.push(`${n} characters, over ${platform === "x" ? "X" : "Bluesky"}'s ${LIMIT[platform]}.`);
  // A post that opens on a handle is threaded as a reply by readers, and replies are never Carrel's.
  if (/^[.\s]*@\w/.test(t)) out.push("It opens with an @handle, which reads as a reply.");
  for (const word of SEED_WORDS) {
    const re = new RegExp(`(?<![\\p{L}'\u2019])${word.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/'/g, "['\u2019]")}(?![\\p{L}])`, "iu");
    if (re.test(t)) out.push(`"${word}" is on the AI-habits list.`);
  }
  if (NOT_JUST.some((re) => re.test(t))) out.push(`The "not X, it's Y" construction.`);
  if (/!\s*$/.test(t) && /!.*!/.test(t)) out.push("More than one exclamation mark.");
  return out;
}

app/routes/book.file.tsx.source:
// The editor for one file in a book: a scene, a bible entry, an outline or the title page. The same
// CodeMirror editor as posts, autosave to D1 as you type, and Save, which commits to Git with the
// version the text started from. Beside a scene: its flags and the bible entries it names.

import { useEffect, useRef, useState } from "react";
import { Link, useFetcher, type ShouldRevalidateFunctionArgs } from "react-router";
import { Alert, Banner } from "capsomer/react/banner";
import { Button } from "capsomer/react/button";
import { ConfirmDialog } from "capsomer/react/confirm-dialog";
import { Disclosure } from "capsomer/react/disclosure";
import { useMessage } from "capsomer/react/message";
import { Panel } from "capsomer/react/panel";
import { Pill, Status } from "capsomer/react/status";
import { Time } from "capsomer/react/time";

import { WritingSurface } from "~/components/editor/writing-surface";
import { useTypingRecede } from "~/components/editor/typing";
import { PageHead } from "~/components/page-head";

import {
  bookRepo,
  checkDraft,
  dismissFinding,
  indexedFile,
  listFiles,
  listFindings,
  requireBookProject,
  saveBookFile,
  type BookWrite,
} from "~/lib/books.server";
import { listAiDrafts, readAiDraft } from "~/lib/ai.server";
import { autosave, discardDraft, readDraft } from "~/lib/content.server";
import { getEnv, getViewer } from "~/lib/context";
import type { Finding } from "~/lib/novels/checks";
import { parseFile } from "~/lib/novels/frontmatter";
import { isBookPath, kindOf, TEMPLATES, titleFromSegment } from "~/lib/novels/layout";
import { can } from "~/lib/roles";

import type { Route } from "./+types/book.file";

const AUTOSAVE_DELAY_MS = 1200;

export function meta({ loaderData: data }: Route.MetaArgs) {
  return [{ title: data ? `${data.label} · ${data.project.name} · Carrel` : "Carrel" }];
}

function starter(path: string, name: string | null, bookName: string): string {
  const kind = kindOf(path);
  const fallback = titleFromSegment(path.split("/").pop()!.replace(/\.md$/, ""));
  if (kind === "scene") return TEMPLATES.scene("");
  if (kind === "character" || kind === "place" || kind === "rule") return TEMPLATES[kind](name?.trim() || fallback);
  if (kind === "book") return ["---", `title: ${bookName}`, "author:", "language: en", "---", "", ""].join("\n");
  return `# ${fallback}\n\n`;
}

function labelFor(path: string): string {
  const kind = kindOf(path);
  const file = titleFromSegment(path.split("/").pop()!.replace(/\.md$/, ""));
  if (kind === "scene") return `${titleFromSegment(path.split("/")[1]!)}: ${file}`;
  if (kind === "book") return "Title page";
  return file;
}

export async function loader({ params, request, context }: Route.LoaderArgs) {
  const env = getEnv(context);
  const viewer = getViewer(context);
  const project = await requireBookProject(env.DB, viewer, params.project, "read");
  const path = params["*"] ?? "";
  if (!isBookPath(path)) throw new Response("Not found", { status: 404 });

  const draft = await readDraft(env.DB, project, viewer, path);
  const { repo, detail } = bookRepo(env);
  let git: { source: string; sha: string } | null = null;
  let gitError: string | null = null;
  if (repo) {
    try {
      git = await repo.read(`${project.book}/${path}`);
    } catch (error) {
      gitError = `Git did not answer (${error instanceof Error ? error.message : String(error)}), so this shows Carrel's index.`;
    }
  }
  // Without Git, the index's copy stands in, read-only for saving but fine for reading.
  const file = git ?? (!repo || gitError ? await indexedFile(env.DB, project, path) : null);
  const canEdit = can(project.role, "edit");
  const fresh = !file && !draft;
  if (fresh && !canEdit) throw new Response("Not found", { status: 404 });

  const kind = kindOf(path);
  const source = draft?.source ?? file?.source ?? starter(path, new URL(request.url).searchParams.get("name"), project.name);

  // The bible entries a scene names, and every world rule, for the side panel.
  let bible: { path: string; name: string; kind: string; body: string }[] = [];
  if (kind === "scene") {
    const { data } = parseFile(source);
    const names = [data.pov, data.location, ...(Array.isArray(data.characters) ? data.characters : [])]
      .filter((n): n is string => typeof n === "string" && n.trim() !== "")
      .map((n) => n.trim().toLowerCase());
    const files = await listFiles(env.DB, project);
    const matched = files.flatMap(({ path, kind, meta }) => {
      if (meta.kind === "rule") return [{ path, kind, name: meta.entry.name }];
      if (meta.kind !== "character" && meta.kind !== "place") return [];
      const hit = [meta.entry.name, ...meta.entry.aliases].some((n) => names.includes(n.toLowerCase()));
      return hit ? [{ path, kind, name: meta.entry.name }] : [];
    });
    bible = await Promise.all(
      matched.map(async (m) => ({
        ...m,
        body: parseFile((await indexedFile(env.DB, project, m.path))?.source ?? "").body.trim().slice(0, 600),
      })),
    );
  }

  return {
    project: { slug: project.slug, name: project.name, book: project.book },
    path,
    kind,
    label: labelFor(path),
    canEdit,
    canPublish: can(project.role, "publish"),
    connected: repo !== null,
    connectionDetail: detail ?? gitError,
    source,
    baseVersion: draft ? draft.baseVersion : (file?.sha ?? null),
    version: git?.sha ?? file?.sha ?? null,
    draftAt: draft?.updatedAt ?? null,
    fresh,
    // Git moved on since this draft was started: saving it would be refused as stale.
    behind: Boolean(draft && git && draft.baseVersion !== git.sha),
    findings: await listFindings(env.DB, project, { path }),
    problems: parseFile(source).problems,
    bible,
    // AI drafts an AI session saved beside this person's own, with their text: never committed.
    aiDrafts: await Promise.all(
      (await listAiDrafts(env.DB, project, viewer, path)).map(async (d) => ({ ...d, source: (await readAiDraft(env.DB, project, viewer, path, d.id)).source })),
    ),
  };
}

type ActionResult =
  | { intent: "autosave"; updatedAt: string }
  | { intent: "discard"; discarded: true }
  | { intent: "check"; findings: Finding[] }
  | { intent: "dismiss"; dismissed: number }
  | { intent: "use-ai-draft"; used: number }
  | { intent: "save"; outcome: BookWrite };

export async function action({ params, request, context }: Route.ActionArgs): Promise<ActionResult> {
  const env = getEnv(context);
  const viewer = getViewer(context);
  const project = await requireBookProject(env.DB, viewer, params.project, "read");
  const path = params["*"] ?? "";
  if (!isBookPath(path)) throw new Response("Not found", { status: 404 });
  const form = await request.formData();
  const intent = String(form.get("intent") ?? "");
  const source = String(form.get("source") ?? "").replace(/\r\n/g, "\n");
  const version = String(form.get("expectedVersion") ?? "") || null;

  switch (intent) {
    case "autosave": {
      const saved = await autosave(env.DB, project, viewer, path, { source, baseVersion: version });
      return { intent, updatedAt: saved.updatedAt };
    }
    case "discard":
      await discardDraft(env.DB, project, viewer, path);
      return { intent, discarded: true };
    case "check":
      return { intent, findings: await checkDraft(env.DB, project, path, source) };
    case "dismiss": {
      const id = Number(form.get("finding"));
      if (!Number.isInteger(id)) throw new Response("Bad request", { status: 400 });
      await dismissFinding(env.DB, project, viewer, id);
      return { intent, dismissed: id };
    }
    case "use-ai-draft": {
      // The person's decision: the AI draft's text becomes their working draft, to edit and save.
      const id = Number(form.get("draft"));
      if (!Number.isInteger(id)) throw new Response("Bad request", { status: 400 });
      const ai = await readAiDraft(env.DB, project, viewer, path, id);
      await autosave(env.DB, project, viewer, path, { source: ai.source, baseVersion: ai.baseVersion });
      return { intent, used: id };
    }
    case "save": {
      const { repo, detail } = bookRepo(env);
      if (!repo) return { intent, outcome: { ok: false, reason: "failed", message: `${detail} Your text is kept here as your draft.` } };
      return { intent, outcome: await saveBookFile(env.DB, repo, project, viewer, path, { source, expectedVersion: version }) };
    }
    default:
      throw new Response("Bad request", { status: 400 });
  }
}

/** Autosave and a check write nothing the page shows, so the page has nothing to reload and Git is not asked. */
export function shouldRevalidate({ formData, defaultShouldRevalidate }: ShouldRevalidateFunctionArgs) {
  const intent = formData?.get("intent");
  if (intent === "autosave" || intent === "check") return false;
  return defaultShouldRevalidate;
}

export default function BookFileRoute({ loaderData }: Route.ComponentProps) {
  return <BookFile key={`${loaderData.project.slug}/${loaderData.path}`} data={loaderData} />;
}

type Ask = { kind: "discard" | "dismiss" | "use-ai"; id?: number; opener: HTMLElement | null };

function BookFile({ data }: { data: Route.ComponentProps["loaderData"] }) {
  const [source, setSource] = useState(data.source);
  // A file started from a template is not saved anywhere yet.
  const [savedSource, setSavedSource] = useState(data.fresh ? "" : data.source);
  const [savedAt, setSavedAt] = useState<string | null>(data.draftAt);
  const [asking, setAsking] = useState<Ask | null>(null);
  const autosaver = useFetcher<ActionResult>();
  const writer = useFetcher<ActionResult>();
  const checker = useFetcher<ActionResult>();
  const { say } = useMessage();
  useTypingRecede();
  const readOnly = !data.canEdit;
  const base = `/b/${data.project.slug}`;

  const inFlight = useRef<string | null>(null);
  useEffect(() => {
    if (readOnly || source === savedSource || autosaver.state !== "idle") return;
    const timer = window.setTimeout(() => {
      inFlight.current = source;
      void autosaver.submit({ intent: "autosave", source, expectedVersion: data.baseVersion ?? "" }, { method: "post" });
    }, AUTOSAVE_DELAY_MS);
    return () => window.clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [source, savedSource, readOnly, data.baseVersion, autosaver.state]);

  useEffect(() => {
    if (autosaver.state !== "idle" || inFlight.current === null) return;
    if (autosaver.data?.intent === "autosave") {
      setSavedSource(inFlight.current);
      setSavedAt(autosaver.data.updatedAt);
    }
    inFlight.current = null;
  }, [autosaver.state, autosaver.data]);

  const discarded = writer.data?.intent === "discard" && writer.state === "idle";
  useEffect(() => {
    if (discarded) {
      setSource(data.source);
      setSavedSource(data.source);
      setSavedAt(null);
    }
  }, [discarded, data.source]);

  // After Use as my draft, the loader has the AI draft as the working copy, which replaces the local one.
  const usedAi = writer.data?.intent === "use-ai-draft" && writer.state === "idle";
  useEffect(() => {
    if (usedAi) {
      setSource(data.source);
      setSavedSource(data.source);
      setSavedAt(data.draftAt);
    }
  }, [usedAi, data.source, data.draftAt]);

  const outcome = writer.data?.intent === "save" ? writer.data.outcome : null;
  useEffect(() => {
    if (outcome?.ok && writer.state === "idle") {
      setSavedSource(source);
      setSavedAt(null);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [outcome, writer.state]);

  // Said once in the message region, as each save finishes.
  const said = useRef<unknown>(null);
  useEffect(() => {
    if (!outcome?.ok || writer.state !== "idle" || said.current === outcome) return;
    said.current = outcome;
    say(`Saved to Git (${outcome.commit.slice(0, 7)}). ${outcome.findings.length === 0 ? "Nothing flagged." : `${outcome.findings.length} flag${outcome.findings.length === 1 ? "" : "s"}; see the list.`}`);
  }, [outcome, writer.state, say]);

  const send = (intent: string, extra: Record<string, string> = {}) =>
    writer.submit({ intent, source, expectedVersion: data.baseVersion ?? "", ...extra }, { method: "post" });

  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === "s") {
        event.preventDefault();
        if (data.canEdit && data.connected && writer.state === "idle") void send("save");
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  });

  const busy = writer.state !== "idle";
  const checked = checker.data?.intent === "check" ? checker.data.findings : null;
  const saveState =
    autosaver.state !== "idle"
      ? "Saving to Carrel"
      : source !== savedSource
        ? "Not yet saved"
        : savedAt
          ? `Draft saved in Carrel ${new Date(savedAt).toLocaleTimeString()}`
          : data.version
            ? "Matches Git"
            : "";
  const openFlags = data.findings.filter((f) => f.status === "open").length;
  const ask = (kind: Ask["kind"], opener: HTMLElement | null, id?: number) => setAsking({ kind, opener, id });

  const crumbs: { label: string; href?: string }[] = [{ label: data.project.name, href: base }];
  if (data.kind === "scene") crumbs.push({ label: titleFromSegment(data.path.split("/")[1]!), href: `${base}/c/${data.path.split("/")[1]}` });
  crumbs.push({ label: data.label });

  return (
    <div className="app-page app-editor">
      <PageHead
        crumbs={crumbs}
        title={data.label}
        lead={
          <>
            <span className="cap-mono">
              {data.project.book}/{data.path}
            </span>{" "}
            {data.version ? null : <Pill variant="outline">Not in Git yet</Pill>}
          </>
        }
      />

      <div className="app-notices">
        {data.connectionDetail ? <Banner tone="warn">{data.connectionDetail}</Banner> : null}
        {data.behind ? (
          <Banner tone="warn" title="Git moved on">
            This file changed in Git after your draft was started, so saving it will be refused. Discard the draft to load Git's version, then reapply your changes.
          </Banner>
        ) : null}
        {data.problems.length > 0 ? (
          <Banner tone="warn" title="The header has lines Carrel does not read">
            {data.problems.map((p) => `line ${p.line}`).join(", ")}. Use key: value, key: [a, b], or one - item per line.
          </Banner>
        ) : null}
      </div>

      <div className="app-editor-grid">
        <div className="app-editor-main">
          <section className="app-editor-pane" aria-label="Write">
            <WritingSurface label={data.kind === "scene" ? "Scene" : "File"} value={source} onChange={setSource} readOnly={readOnly} linkTargets={[]} />
          </section>
        </div>

        <aside className="app-editor-side" aria-label="Saving, checks and the bible">
          {data.canEdit ? (
            <Panel title="This file" src={data.version ? "In Git" : "Only in Carrel so far"}>
              <div className="app-stack" data-tight>
                <p role="status" className="app-savestate">
                  {saveState}
                </p>
                {outcome && !outcome.ok ? <Alert tone="crit">{outcome.message}</Alert> : null}
                <div className="app-actions">
                  <Button variant="primary" pending={busy} disabledReason={!data.connected ? "Git is not connected, so saving waits. Your text is kept here as your draft." : undefined} onClick={() => send("save")}>
                    Save to Git
                  </Button>
                  <Button pending={checker.state !== "idle"} onClick={() => checker.submit({ intent: "check", source }, { method: "post" })}>
                    Check this text
                  </Button>
                  {savedAt ? (
                    <Button variant="quiet" pending={busy} onClick={(event) => ask("discard", event.currentTarget)}>
                      Discard my draft
                    </Button>
                  ) : null}
                </div>
              </div>
            </Panel>
          ) : null}

          <Panel title="Flags" count={openFlags} src="From the last save" id="flags">
            <div className="app-stack" data-tight>
              <p className="cap-muted app-note">A flag never stops a save; it holds export until it is fixed or the Owner dismisses it.</p>
              {data.findings.length === 0 ? (
                <p>None.</p>
              ) : (
                <ul className="app-flags" aria-label="Flags on this file">
                  {data.findings.map((f) => (
                    <li key={f.id}>
                      {f.status === "open" ? <Status tone="warn">Open</Status> : <Pill variant="secondary">Dismissed</Pill>}
                      <span>
                        <strong>{f.check}</strong> {f.line ? <span className="cap-muted">line {f.line}</span> : null} {f.message}
                      </span>
                      {f.status === "open" && data.canPublish ? (
                        <Button size="sm" onClick={(event) => ask("dismiss", event.currentTarget, f.id)}>
                          Dismiss<span className="cap-sr-only"> flag: {f.message}</span>
                        </Button>
                      ) : null}
                    </li>
                  ))}
                </ul>
              )}
              {checked ? (
                <div role="status" className="app-stack" data-tight>
                  <h3 className="app-subhead">This text, checked now</h3>
                  {checked.length === 0 ? (
                    <p>Nothing flagged.</p>
                  ) : (
                    <ul className="app-flags">
                      {checked.map((f, i) => (
                        <li key={i}>
                          <Status tone="warn">Found</Status>
                          <span>
                            <strong>{f.check}</strong> {f.line ? <span className="cap-muted">line {f.line}</span> : null} {f.message}
                          </span>
                        </li>
                      ))}
                    </ul>
                  )}
                </div>
              ) : null}
            </div>
          </Panel>

          {data.aiDrafts.length > 0 ? (
            <Panel title="AI drafts beside yours" count={data.aiDrafts.length} src="None has touched your draft or Git">
              <div className="app-stack" data-tight>
                {data.aiDrafts.map((d) => (
                  <Disclosure
                    key={d.id}
                    summary={
                      <>
                        {d.client}{" "}
                        <span className="cap-muted">
                          <Time at={d.createdAt} /> · {d.words} words
                        </span>
                      </>
                    }
                  >
                    {d.note ? <p>{d.note}</p> : null}
                    <p className="app-bible-body">{d.source}</p>
                    {data.canEdit ? (
                      <Button size="sm" pending={busy} onClick={(event) => ask("use-ai", event.currentTarget, d.id)}>
                        Use as my draft
                      </Button>
                    ) : null}
                  </Disclosure>
                ))}
              </div>
            </Panel>
          ) : null}

          {data.kind === "scene" ? (
            <Panel title="From the bible" count={data.bible.length}>
              {data.bible.length === 0 ? (
                <p className="cap-muted">No entries match this scene's header.</p>
              ) : (
                <div className="app-stack" data-tight>
                  {data.bible.map((b) => (
                    <Disclosure
                      key={b.path}
                      summary={
                        <>
                          {b.name} <span className="cap-muted">{b.kind}</span>
                        </>
                      }
                    >
                      <p className="app-bible-body">{b.body || "(no notes)"}</p>
                      <Link to={`${base}/f/${b.path}`}>Open</Link>
                    </Disclosure>
                  ))}
                </div>
              )}
            </Panel>
          ) : null}
        </aside>
      </div>

      <ConfirmDialog
        open={asking?.kind === "discard"}
        title="Discard your draft?"
        lead="Your working copy in Carrel is deleted, and the editor goes back to Git's text. This cannot be undone."
        body={[]}
        action="Discard my draft"
        returnTo={asking?.opener}
        perform={async () => void (await writer.submit({ intent: "discard" }, { method: "post" }))}
        onClose={() => setAsking(null)}
      />
      <ConfirmDialog
        open={asking?.kind === "dismiss"}
        title="Dismiss this flag?"
        lead="A dismissed flag no longer holds export, and it cannot be reopened."
        body={asking?.id !== undefined ? [data.findings.find((f) => f.id === asking.id)?.message ?? ""] : []}
        action="Dismiss flag"
        returnTo={asking?.opener}
        perform={async () => {
          if (asking?.id !== undefined) await writer.submit({ intent: "dismiss", finding: String(asking.id) }, { method: "post" });
        }}
        onClose={() => setAsking(null)}
      />
      <ConfirmDialog
        open={asking?.kind === "use-ai"}
        title="Use the AI draft as your draft?"
        lead="Its text replaces your working draft, which you then edit and save as usual. Your current draft is not kept."
        body={[]}
        action="Replace my draft"
        returnTo={asking?.opener}
        perform={async () => {
          if (asking?.id !== undefined) await writer.submit({ intent: "use-ai-draft", draft: String(asking.id) }, { method: "post" });
        }}
        onClose={() => setAsking(null)}
      />
    </div>
  );
}

app/routes/mentions.api.ts.source:
// The Mentions screen's write endpoint: approve, reject or delete the chosen mentions, or sweep the
// expired ones, answered as JSON with an outcome for every mention. Roles are checked in
// mentions.server.ts (the Owner's alone, before the site is asked anything). POST only.

import { getEnv, getViewer } from "~/lib/context";
import { decideMentions, sweepMentions, type MentionOp } from "~/lib/mentions.server";
import { requireSiteProject } from "~/lib/projects.server";

import type { Route } from "./+types/mentions.api";

const OPS = ["approve", "reject", "delete"] as const;

export async function action({ params, request, context }: Route.ActionArgs) {
  if (request.method !== "POST") return Response.json({ error: "Method not allowed." }, { status: 405 });
  const env = getEnv(context);
  const viewer = getViewer(context);
  try {
    // Refused on the role before the body is read: a request from anyone but the Owner never reaches the site.
    const project = await requireSiteProject(env.DB, viewer, params.project, "decide_mention");
    const form = await request.formData();
    const op = String(form.get("op") ?? "");
    if (op === "sweep") return Response.json({ sweep: await sweepMentions(env, project, { viewer }) });
    if (!(OPS as readonly string[]).includes(op)) return Response.json({ error: "That is not a mention action." }, { status: 400 });
    let items: unknown;
    try {
      items = JSON.parse(String(form.get("items") ?? "[]"));
    } catch {
      return Response.json({ error: "The chosen mentions were not readable." }, { status: 400 });
    }
    return Response.json({ results: await decideMentions(env, project, { viewer }, op as MentionOp, items) });
  } catch (thrown) {
    if (!(thrown instanceof Response)) throw thrown;
    if (thrown.status === 403) return Response.json({ error: "Deciding mentions is the Owner's step." }, { status: 403 });
    return Response.json({ error: (await thrown.text()) || "The request was not accepted." }, { status: thrown.status });
  }
}

workers/gate.ts.source:
// The browser door. Nothing renders until Access has vouched for the request and the email it
// carries belongs to an active person in Carrel. Kept apart from app.ts so tests can drive it without
// the React Router build.
//
// This is the only door on carrel.dustinedwards.info. The AI door is a different hostname,
// carrel-mcp.dustinedwards.info, served by app/lib/mcp/door.ts and chosen in app.ts by the host
// alone (design decision 7, corrected 2026-09-27). So a browser session is never treated as AI, and
// an AI session never reaches the buttons: /mcp here is just a page that does not exist, behind
// Access like every other.

import type { JWTVerifyGetKey } from "jose";

import { accessKeys, verifyAccess } from "~/lib/access.server";
import { findViewer, type Viewer } from "~/lib/people.server";

export type Render = (request: Request, viewer: Viewer) => Promise<Response>;

const PRIVATE_HEADERS: Record<string, string> = {
  "Cache-Control": "private, no-store",
  "Strict-Transport-Security": "max-age=31536000",
  "X-Content-Type-Options": "nosniff",
  "X-Frame-Options": "DENY",
  "Referrer-Policy": "no-referrer",
};

function withPrivateHeaders(response: Response): Response {
  const out = new Response(response.body, response);
  // The preview route alone may be framed, and only by Carrel itself; nothing can loosen it further.
  const framedByCarrel = response.headers.get("X-Frame-Options")?.toUpperCase() === "SAMEORIGIN";
  for (const [name, value] of Object.entries(PRIVATE_HEADERS)) out.headers.set(name, value);
  // An HTML page is left as it is: Cloudflare does not touch a response that says no-transform, which
  // keeps the Web Analytics beacon out of private pages (a dashboard exclusion needs the Pro plan).
  // Scripts, styles and fonts stay compressible. One Cache-Control header, never two.
  if (out.headers.get("Content-Type")?.toLowerCase().startsWith("text/html")) {
    out.headers.set("Cache-Control", `${PRIVATE_HEADERS["Cache-Control"]}, no-transform`);
  }
  if (framedByCarrel) out.headers.set("X-Frame-Options", "SAMEORIGIN");
  return out;
}

/** The same bare 403 for every refusal, so a caller learns nothing about why. The reason is logged. */
function refuse(reason: string): Response {
  console.warn(JSON.stringify({ gate: "refused", reason }));
  return withPrivateHeaders(
    new Response("Forbidden", { status: 403, headers: { "Content-Type": "text/plain; charset=utf-8" } }),
  );
}

export async function gate(
  request: Request,
  env: Env,
  render: Render,
  keys: JWTVerifyGetKey = accessKeys(env.ACCESS_TEAM_DOMAIN),
): Promise<Response> {
  let viewer: Viewer | null;
  try {
    const access = await verifyAccess(request, { teamDomain: env.ACCESS_TEAM_DOMAIN, audience: env.ACCESS_AUD }, keys);
    if (!access.ok) return refuse(access.reason);
    viewer = await findViewer(env.DB, access.email);
  } catch (error) {
    return refuse(`error: ${error instanceof Error ? error.message : String(error)}`);
  }
  if (!viewer) return refuse("unknown-person");
  // A reviewer is an AI agent, not a person: it has no business at the browser door.
  if (viewer.isReviewer) return refuse("reviewer-at-browser-door");
  return withPrivateHeaders(await render(request, viewer));
}

test/content.test.ts.source:
// Planted problems for writes to a site (design section 7, "Access, roles, key"): a Reader saves, an
// Editor publishes, an Editor changes a live post, a non-member reads, and a stale expectedVersion.
// Each must be refused, and refused before the site is asked to change anything.

import { beforeEach, describe, expect, it } from "vitest";

import { autosave, readDraft, writeToSite } from "~/lib/content.server";
import { requireSiteProject } from "~/lib/projects.server";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";

async function refusal(promise: Promise<unknown>): Promise<number> {
  try {
    await promise;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
  throw new Error("expected a refusal, and the call succeeded");
}

let projectId: number;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  await addPerson("stranger@test.invalid");
  projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  await share(projectId, reader, "reader");
});

async function as(email: string, action: "read" | "edit" | "publish" = "read") {
  const viewer = await viewerFor(email);
  return { viewer, project: await requireSiteProject(testEnv.DB, viewer, SLUG, action) };
}

/** A post already on the site, saved by the Owner, returned with its current version. */
async function seed(site: ReturnType<typeof fakeSite>, env: Env, status: "draft" | "published" = "draft") {
  const { viewer, project } = await as("owner@test.invalid");
  const saved = await writeToSite(env, project, viewer, "post-one", { action: "save", source: "# One\n", expectedVersion: null }, site.fetch);
  if (!saved.ok) throw new Error(saved.message);
  if (status === "draft") return saved.version;
  const published = await writeToSite(env, project, viewer, "post-one", { action: "publish", expectedVersion: saved.version }, site.fetch);
  if (!published.ok) throw new Error(published.message);
  return published.version;
}

function writesTo(site: ReturnType<typeof fakeSite>) {
  return site.requests.filter((r) => !r.startsWith("GET"));
}

describe("PLANT: a non-member reads", () => {
  it("is answered 404, the same as a project that does not exist", async () => {
    const stranger = await viewerFor("stranger@test.invalid");
    expect(await refusal(requireSiteProject(testEnv.DB, stranger, SLUG, "read"))).toBe(404);
    expect(await refusal(requireSiteProject(testEnv.DB, stranger, "no-such-project", "read"))).toBe(404);
  });

  it("is answered 404 for a project that is not a site", async () => {
    await addProject("a-book");
    const owner = await viewerFor("owner@test.invalid");
    expect(await refusal(requireSiteProject(testEnv.DB, owner, "a-book", "read"))).toBe(404);
  });
});

describe("PLANT: a Reader saves", () => {
  it("is refused for autosave and for a save to the site, and the site hears nothing", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const { viewer, project } = await as("reader@test.invalid");
    expect(await refusal(autosave(env.DB, project, viewer, "post-one", { source: "x", baseVersion: null }))).toBe(403);
    expect(
      await refusal(writeToSite(env, project, viewer, "post-one", { action: "save", source: "x", expectedVersion: null }, site.fetch)),
    ).toBe(403);
    expect(site.requests).toEqual([]);
  });
});

describe("PLANT: an Editor publishes", () => {
  it("is refused for publish, schedule and unpublish before any request", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const version = await seed(site, env);
    site.requests.length = 0;
    const { viewer, project } = await as("editor@test.invalid");
    for (const request of [
      { action: "publish" as const, expectedVersion: version },
      { action: "schedule" as const, expectedVersion: version, publishAt: "2030-01-01T00:00:00Z" },
      { action: "unpublish" as const, expectedVersion: version },
    ]) {
      expect(await refusal(writeToSite(env, project, viewer, "post-one", request, site.fetch)), request.action).toBe(403);
    }
    expect(site.requests).toEqual([]);
  });

  it("is refused when the change would alter a live post, since that is a publish", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const version = await seed(site, env, "published");
    site.requests.length = 0;
    const { viewer, project } = await as("editor@test.invalid");
    expect(
      await refusal(writeToSite(env, project, viewer, "post-one", { action: "save", source: "# Changed live\n", expectedVersion: version }, site.fetch)),
    ).toBe(403);
    expect(writesTo(site)).toEqual([]);
    expect(site.adapter.store.get("post-one")!.doc.source).toBe("# One\n");
  });

  it("lets an Editor save a draft, and records who did it", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const version = await seed(site, env);
    const { viewer, project } = await as("editor@test.invalid");
    const outcome = await writeToSite(env, project, viewer, "post-one", { action: "save", source: "# One, edited\n", expectedVersion: version }, site.fetch);
    expect(outcome).toMatchObject({ ok: true, status: "draft" });
    const change = await testEnv.DB.prepare("SELECT person_id, action, version_before FROM changes WHERE id = ?")
      .bind(outcome.ok ? outcome.changeId : "")
      .first();
    expect(change).toEqual({ person_id: viewer.id, action: "save", version_before: version });
  });
});

describe("PLANT: a stale expectedVersion", () => {
  it("is refused by the site, reported as a conflict, and the person's draft is kept", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const version = await seed(site, env);
    const { viewer, project } = await as("owner@test.invalid");
    // Someone else moves the post on.
    const moved = await writeToSite(env, project, viewer, "post-one", { action: "save", source: "# Moved\n", expectedVersion: version }, site.fetch);
    expect(moved.ok).toBe(true);

    await autosave(env.DB, project, viewer, "post-one", { source: "# My edit\n", baseVersion: version });
    const stale = await writeToSite(env, project, viewer, "post-one", { action: "save", source: "# My edit\n", expectedVersion: version }, site.fetch);
    expect(stale).toMatchObject({ ok: false, reason: "conflict" });
    expect(site.adapter.store.get("post-one")!.doc.source).toBe("# Moved\n");
    expect((await readDraft(env.DB, project, viewer, "post-one"))?.source).toBe("# My edit\n");
  });

  it("refuses a create over a slug the site already holds", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    await seed(site, env);
    const { viewer, project } = await as("owner@test.invalid");
    const clobber = await writeToSite(env, project, viewer, "post-one", { action: "save", source: "# Clobber\n", expectedVersion: null }, site.fetch);
    expect(clobber).toMatchObject({ ok: false, reason: "conflict" });
  });
});

describe("the Owner's writes", () => {
  it("publish, index the result, record the change, and clear the draft that was sent", async () => {
    const site = fakeSite();
    const env = connectedEnv();
    const version = await seed(site, env);
    const { viewer, project } = await as("owner@test.invalid");
    await autosave(env.DB, project, viewer, "post-one", { source: "# One, final\n", baseVersion: version });
    const outcome = await writeToSite(
      env,
      project,
      viewer,
      "post-one",
      { action: "publish", expectedVersion: version, source: "# One, final\n" },
      site.fetch,
    );
    expect(outcome).toMatchObject({ ok: true, status: "published" });
    expect(site.adapter.store.get("post-one")!.doc.source).toBe("# One, final\n");
    expect(await readDraft(env.DB, project, viewer, "post-one")).toBeNull();
    const indexed = await testEnv.DB.prepare("SELECT status, title FROM site_items WHERE project_id = ? AND item_id = ?")
      .bind(projectId, "post-one")
      .first();
    expect(indexed).toEqual({ status: "published", title: "One, final" });
    const count = await testEnv.DB.prepare("SELECT COUNT(*) AS n FROM changes").first<{ n: number }>();
    expect(count!.n).toBe(2);
  });

  it("reports a site that is not connected rather than failing obscurely", async () => {
    const { viewer, project } = await as("owner@test.invalid");
    await expect(
      writeToSite(testEnv, project, viewer, "post-one", { action: "save", source: "x", expectedVersion: null }),
    ).rejects.toThrow(/No SITE_DUSTINEDWARDS_KEY set/);
  });
});

test/health.test.ts.source:
// Planted problems for the health check: one email per change of state, never one per run, and an
// alert that fails to send is retried rather than lost.

import { beforeEach, describe, expect, it } from "vitest";
import { memoryAdapter } from "@dustinedwards/site-api/testing";

import { runHealth } from "~/lib/health.server";
import { clearTokenCache } from "~/lib/novels/repo.server";
import { addPerson, resetDb, testEnv } from "./env";
import { fakeNovels, githubStyleKey } from "./novels";
import { connectedEnv, fakeSite, SITE_ORIGIN } from "./site";

type Sent = { subject: string; text: string; to: string };

function mailbox(fail = false) {
  const sent: Sent[] = [];
  const EMAIL = {
    async send(message: Sent) {
      if (fail) throw new Error("send failed");
      sent.push(message);
      return { messageId: `m${sent.length}` };
    },
  } as unknown as SendEmail;
  return { sent, EMAIL };
}

const certsOk = async () => Response.json({ keys: [{ kid: "k" }] });
const certsDown = async () => new Response("down", { status: 503 });

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
});

describe("health", () => {
  it("sends nothing on a first run where every check passes", async () => {
    const box = mailbox();
    const { results, emailed } = await runHealth({ ...testEnv, EMAIL: box.EMAIL }, certsOk);
    expect(results.every((r) => r.ok)).toBe(true);
    expect(emailed).toBe(false);
    expect(box.sent).toHaveLength(0);
  });

  it("sends one email when a check starts failing, and none while it stays failing", async () => {
    const box = mailbox();
    const env = { ...testEnv, EMAIL: box.EMAIL };
    await runHealth(env, certsOk);
    await runHealth(env, certsDown);
    await runHealth(env, certsDown);
    expect(box.sent).toHaveLength(1);
    expect(box.sent[0]!.subject).toBe("Carrel: 1 check failing");
    expect(box.sent[0]!.text).toContain("FAIL access-keys");
    expect(box.sent[0]!.to).toBe("owner@test.invalid");
  });

  it("sends one email on recovery", async () => {
    const box = mailbox();
    const env = { ...testEnv, EMAIL: box.EMAIL };
    await runHealth(env, certsDown);
    await runHealth(env, certsOk);
    expect(box.sent.map((m) => m.subject)).toEqual(["Carrel: 1 check failing", "Carrel: all checks pass"]);
  });

  it("flags a database with no Owner", async () => {
    await resetDb();
    const box = mailbox();
    await runHealth({ ...testEnv, EMAIL: box.EMAIL }, certsOk);
    expect(box.sent).toHaveLength(1);
    expect(box.sent[0]!.text).toContain("FAIL owner");
  });

  it("flags a missing ACCESS_AUD and a placeholder alert address", async () => {
    const box = mailbox();
    await runHealth({ ...testEnv, ACCESS_AUD: "", ALERT_EMAIL: "alerts@example.com", EMAIL: box.EMAIL }, certsOk);
    expect(box.sent[0]!.text).toMatch(/FAIL config: Missing or placeholder: ACCESS_AUD, ALERT_EMAIL/);
  });

  it("keeps the alert pending when the email fails, and sends it on the next run", async () => {
    const failing = mailbox(true);
    const first = await runHealth({ ...testEnv, EMAIL: failing.EMAIL }, certsDown);
    expect(first.emailed).toBe(false);

    const working = mailbox();
    const second = await runHealth({ ...testEnv, EMAIL: working.EMAIL }, certsDown);
    expect(second.emailed).toBe(true);
    expect(working.sent).toHaveLength(1);
  });
});

// Stage 2: each site's key and its conformance to the site-api contract (design section 7, "Health":
// a changed schema hash sends one email).
describe("site health", () => {
  function through(site: ReturnType<typeof fakeSite>, drift = false) {
    return async (url: string, init?: RequestInit) => {
      if (!url.startsWith(SITE_ORIGIN)) return certsOk();
      const response = await site.fetch(url, init);
      if (!drift || !url.endsWith("/meta") || !response.ok) return response;
      const meta = (await response.json()) as Record<string, unknown>;
      return Response.json({ ...meta, schemaHash: "f".repeat(64), packageVersion: "0.2.0" });
    };
  }

  it("counts a site with no key as not connected, which is not a failure", async () => {
    const { results } = await runHealth({ ...testEnv, EMAIL: mailbox().EMAIL }, certsOk);
    expect(results.find((r) => r.name === "site-dustinedwards")).toEqual({
      name: "site-dustinedwards",
      ok: true,
      detail: "Not connected: No SITE_DUSTINEDWARDS_KEY set.",
    });
  });

  it("PLANT: flags a key too short to be the site's", async () => {
    const box = mailbox();
    await runHealth({ ...connectedEnv({ SITE_DUSTINEDWARDS_KEY: "short" }), EMAIL: box.EMAIL }, certsOk);
    expect(box.sent[0]!.text).toMatch(/FAIL site-dustinedwards: SITE_DUSTINEDWARDS_KEY is shorter than 32/);
  });

  it("passes a conforming site, and its write probe changes nothing there", async () => {
    const site = fakeSite();
    const box = mailbox();
    const { results } = await runHealth({ ...connectedEnv(), EMAIL: box.EMAIL }, through(site));
    expect(results.find((r) => r.name === "site-dustinedwards")?.ok).toBe(true);
    expect(box.sent).toHaveLength(0);
    expect(site.adapter.store.size).toBe(0);
  });

  it("includes the mentions group when the site declares it, and its probe changes nothing there", async () => {
    const site = fakeSite();
    const id = site.adapter.receiveMention({ sourceUrl: "https://a.example/post", targetId: "first-post" });
    const before = structuredClone(site.adapter.mentionStore.get(id));
    const box = mailbox();
    const { results } = await runHealth({ ...connectedEnv(), EMAIL: box.EMAIL }, through(site));
    expect(results.find((r) => r.name === "site-dustinedwards")?.ok).toBe(true);
    const asked = site.requests.filter((r) => r.includes("/mentions"));
    // The probe ran against the real mention (a stale version, so refused), and nothing deleted or swept it.
    expect(asked).toContain(`POST /api/carrel/v1/mentions/${id}/decide`);
    expect(asked).not.toContain(`DELETE /api/carrel/v1/mentions/${id}`);
    expect(site.adapter.mentionStore.get(id)).toEqual(before);
    expect(site.adapter.purged).toEqual([]);
    expect(box.sent).toHaveLength(0);
  });

  it("PLANT: a site that decides a mention it does not hold is flagged, by the mentions check", async () => {
    const site = fakeSite();
    site.adapter.mentions!.decide = async () => ({ status: "approved", version: "m9", purged: null });
    const box = mailbox();
    await runHealth({ ...connectedEnv(), EMAIL: box.EMAIL }, through(site));
    expect(box.sent[0]!.text).toMatch(/FAIL site-dustinedwards: dustinedwards\.info does not conform\. mention decide of an unknown id/);
  });

  it("a site without the mentions group still conforms: its mentions routes answer 501", async () => {
    const site = fakeSite(memoryAdapter({ mentions: false }));
    const { results } = await runHealth({ ...connectedEnv(), EMAIL: mailbox().EMAIL }, through(site));
    expect(results.find((r) => r.name === "site-dustinedwards")?.ok).toBe(true);
  });

  it("PLANT: a changed schema hash sends one email, and none while it stays changed", async () => {
    const site = fakeSite();
    const box = mailbox();
    const env = { ...connectedEnv(), EMAIL: box.EMAIL };
    await runHealth(env, through(site));
    await runHealth(env, through(site, true));
    await runHealth(env, through(site, true));
    expect(box.sent).toHaveLength(1);
    expect(box.sent[0]!.text).toMatch(/FAIL site-dustinedwards: dustinedwards\.info does not conform\. meta: answers with this contract's schema hash: schema hash ffffffffffff/);
  });

  it("PLANT: flags a site that holds a different key", async () => {
    const site = fakeSite();
    const box = mailbox();
    await runHealth({ ...connectedEnv({ SITE_DUSTINEDWARDS_KEY: "another-key-of-the-right-length-0123456789" }), EMAIL: box.EMAIL }, through(site));
    expect(box.sent[0]!.text).toContain("FAIL site-dustinedwards");
  });
});

// Stage 4: the GitHub App for the novels repository (design section 5, "Health": the GitHub App token).
describe("novels health", () => {
  beforeEach(() => clearTokenCache());

  function through(gh: ReturnType<typeof fakeNovels>) {
    return async (url: string, init?: RequestInit) => (url.startsWith("https://api.github.com") ? gh.fetch(url, init) : certsOk());
  }

  it("counts an App not set up yet as not connected, which is not a failure", async () => {
    const { results } = await runHealth({ ...testEnv, EMAIL: mailbox().EMAIL }, certsOk);
    expect(results.find((r) => r.name === "novels")).toMatchObject({ ok: true, detail: expect.stringMatching(/^Not connected: /) });
  });

  it("PLANT: flags half a setup, an App id with no key", async () => {
    const box = mailbox();
    await runHealth({ ...testEnv, NOVELS_APP_ID: "123", EMAIL: box.EMAIL }, certsOk);
    expect(box.sent[0]!.text).toContain("FAIL novels: NOVELS_APP_PRIVATE_KEY is missing");
  });

  it("passes when the App gets a token for the repository", async () => {
    const key = await githubStyleKey();
    const { results } = await runHealth(
      { ...testEnv, NOVELS_APP_ID: "123", NOVELS_APP_PRIVATE_KEY: key.pkcs1Pem, EMAIL: mailbox().EMAIL },
      through(fakeNovels()),
    );
    expect(results.find((r) => r.name === "novels")).toEqual({ name: "novels", ok: true, detail: "The GitHub App can write to DrDustinEdwards/novels." });
  });

  it("PLANT: flags an App GitHub will not answer for", async () => {
    const key = await githubStyleKey();
    const box = mailbox();
    const refused = async (url: string) => (url.startsWith("https://api.github.com") ? new Response("{}", { status: 404 }) : certsOk());
    await runHealth({ ...testEnv, NOVELS_APP_ID: "123", NOVELS_APP_PRIVATE_KEY: key.pkcs1Pem, EMAIL: box.EMAIL }, refused);
    expect(box.sent[0]!.text).toContain("FAIL novels: The GitHub App could not reach DrDustinEdwards/novels: GitHub did not find the App's installation");
  });
});

