// Planted problems for the gate. Every refusal case must be a bare 403 and must never reach render.

import { createLocalJWKSet, exportJWK, generateKeyPair, SignJWT, type JWK } from "jose";
import { beforeAll, beforeEach, describe, expect, it } from "vitest";

import { gate } from "../workers/gate";
import { addPerson, resetDb, testEnv } from "./env";

const ISSUER = "https://test-team.cloudflareaccess.com";
const AUDIENCE = "test-audience-tag";

let keys: ReturnType<typeof createLocalJWKSet>;
let signingKey: CryptoKey;
let strangerKey: CryptoKey;

beforeAll(async () => {
  const pair = await generateKeyPair("RS256", { extractable: true });
  const stranger = await generateKeyPair("RS256", { extractable: true });
  signingKey = pair.privateKey;
  strangerKey = stranger.privateKey;
  const jwk: JWK = { ...(await exportJWK(pair.publicKey)), kid: "test", alg: "RS256" };
  keys = createLocalJWKSet({ keys: [jwk] });
});

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  await addPerson("gone@test.invalid", { disabled: true });
});

type Claims = { email?: string; iss?: string; aud?: string; exp?: number };

async function token(claims: Claims = {}, key: CryptoKey = signingKey): Promise<string> {
  const { email = "owner@test.invalid", iss = ISSUER, aud = AUDIENCE, exp } = claims;
  const jwt = new SignJWT(email ? { email } : {})
    .setProtectedHeader({ alg: "RS256", kid: "test" })
    .setIssuer(iss)
    .setAudience(aud)
    .setIssuedAt();
  jwt.setExpirationTime(exp ?? "5m");
  return jwt.sign(key);
}

function request(jwt?: string): Request {
  const headers = new Headers();
  if (jwt !== undefined) headers.set("Cf-Access-Jwt-Assertion", jwt);
  return new Request("https://carrel.test/", { headers });
}

async function run(req: Request, env: Env = testEnv) {
  let rendered = false;
  const response = await gate(req, env, async () => {
    rendered = true;
    return new Response("inside");
  }, keys);
  return { response, rendered };
}

async function expectRefused(req: Request, env?: Env) {
  const { response, rendered } = await run(req, env);
  expect(response.status).toBe(403);
  expect(await response.text()).toBe("Forbidden");
  expect(response.headers.get("cache-control")).toBe("private, no-store");
  expect(rendered).toBe(false);
}

describe("gate: refusals (fail closed)", () => {
  it("refuses a request with no Access token", async () => {
    await expectRefused(request());
  });

  it("refuses an empty token", async () => {
    await expectRefused(request(""));
  });

  it("refuses a token that is not a JWT", async () => {
    await expectRefused(request("not-a-jwt"));
  });

  it("refuses a token signed by a key the team does not publish", async () => {
    await expectRefused(request(await token({}, strangerKey)));
  });

  it("refuses the wrong audience", async () => {
    await expectRefused(request(await token({ aud: "some-other-app" })));
  });

  it("refuses the wrong issuer", async () => {
    await expectRefused(request(await token({ iss: "https://other-team.cloudflareaccess.com" })));
  });

  it("refuses an expired token", async () => {
    await expectRefused(request(await token({ exp: Math.floor(Date.now() / 1000) - 3600 })));
  });

  it("refuses a valid token with no email", async () => {
    await expectRefused(request(await token({ email: "" })));
  });

  it("refuses an email Access admitted but Carrel does not know", async () => {
    await expectRefused(request(await token({ email: "stranger@test.invalid" })));
  });

  it("refuses a disabled person", async () => {
    await expectRefused(request(await token({ email: "gone@test.invalid" })));
  });

  it("refuses everyone when ACCESS_AUD is not set", async () => {
    await expectRefused(request(await token()), { ...testEnv, ACCESS_AUD: "" });
  });

  it("refuses everyone when the team domain is not set", async () => {
    await expectRefused(request(await token()), { ...testEnv, ACCESS_TEAM_DOMAIN: "" });
  });
});

describe("gate: admission", () => {
  it("admits a valid token for a known person and passes the viewer to render", async () => {
    let seen = "";
    const response = await gate(request(await token()), testEnv, async (_req, viewer) => {
      seen = viewer.email;
      return new Response("inside");
    }, keys);
    expect(response.status).toBe(200);
    expect(await response.text()).toBe("inside");
    expect(seen).toBe("owner@test.invalid");
    expect(response.headers.get("cache-control")).toBe("private, no-store");
  });

  it("leaves an HTML page untransformed so Web Analytics cannot inject its beacon, and no asset", async () => {
    const through = async (type: string) =>
      gate(request(await token()), testEnv, async () => new Response("x", { headers: { "Content-Type": type } }), keys);
    for (const html of ["text/html; charset=utf-8", "TEXT/HTML"]) {
      expect((await through(html)).headers.get("cache-control")).toBe("private, no-store, no-transform");
    }
    for (const asset of ["text/css", "text/javascript", "font/woff2", "application/json", "text/plain; charset=utf-8"]) {
      expect((await through(asset)).headers.get("cache-control"), asset).toBe("private, no-store");
    }
  });

  it("matches the email without regard to case", async () => {
    const { response } = await run(request(await token({ email: "Owner@Test.Invalid" })));
    expect(response.status).toBe(200);
  });

  it("accepts the team domain written with a trailing slash", async () => {
    const env = { ...testEnv, ACCESS_TEAM_DOMAIN: `${ISSUER}/` };
    const { response } = await run(request(await token()), env);
    expect(response.status).toBe(200);
  });
});

test/media.test.ts.source:
// The media library (stage 3) over site-api v0.2.0's media group. The site is site-api's own handler
// over its reference adapter, whose reference check scans post sources for /media/<id> as
// dustinedwards.info's does. Planted: each role refusal, a delete of a file a post uses (refused with
// the post named), an upload the site would refuse (never sent), and bytes the site API refuses.

import { memoryAdapter } from "@dustinedwards/site-api/testing";
import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { runHealth } from "~/lib/health.server";
import { deleteMedia, listMedia, mediaDetail, mediaLimits, uploadMedia } from "~/lib/media.server";
import { requireSiteProject } from "~/lib/projects.server";
import { figureMarkup } from "~/lib/site-markdown";
import { loader as editorLoader } from "~/routes/editor";
import { action as mediaAction, loader as mediaLoader } from "~/routes/media";
import { action as apiAction, loader as apiLoader } from "~/routes/media.api";

import { appPolicy } from "../workers/csp";
import { addPerson, addProject, resetDb, share } from "./env";
import { connectedEnv, fakeSite, SITE_ORIGIN, viewerFor } from "./site";

const SLUG = "de-info";
const PNG = Uint8Array.from(
  atob("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg=="),
  (c) => c.charCodeAt(0),
);

let site: ReturnType<typeof fakeSite<ReturnType<typeof memoryAdapter>>>;
let env: Env;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  await addPerson("stranger@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, editor, "editor");
  await share(id, reader, "reader");
  site = fakeSite();
  env = connectedEnv();
  vi.stubGlobal("fetch", site.fetch);
});

async function project(email: string, action: Parameters<typeof requireSiteProject>[3] = "read") {
  return requireSiteProject(env.DB, await viewerFor(email), SLUG, action);
}

async function actor(email: string) {
  return { viewer: await viewerFor(email) };
}

function file(bytes: Uint8Array, name = "river.png", type = "image/png") {
  return { name, type, size: bytes.byteLength, bytes: async () => bytes.slice().buffer };
}

async function status(run: () => Promise<unknown>): Promise<number> {
  try {
    await run();
    return 200;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
}

async function contextFor(email: string, e: Env = env) {
  const context = new RouterContextProvider();
  context.set(cloudflareContext, { env: e, ctx: {} as ExecutionContext });
  context.set(viewerContext, await viewerFor(email));
  context.set(nonceContext, "n");
  return context;
}

/** A file on the site, uploaded as the site would take it from anyone. */
async function seedFile(name = "river.png") {
  return site.adapter.media!.upload({ bytes: PNG, contentType: "image/png", filename: name, alt: "The river", changeId: "seed" });
}

describe("the library through the site API", () => {
  it("lists, searches and reads a file with its uses, and shows it at the site's own address", async () => {
    const item = await seedFile();
    const reader = await project("reader@test.invalid");
    const list = await listMedia(env, reader, {});
    expect(list.items).toMatchObject([{ id: item.id, url: `/media/${item.id}`, src: `${SITE_ORIGIN}/media/${item.id}`, alt: "The river" }]);
    expect((await listMedia(env, reader, { q: "nothing-like-it" })).items).toEqual([]);
    expect(await mediaDetail(env, reader, item.id)).toMatchObject({ id: item.id, usedBy: [] });
    expect(await mediaDetail(env, reader, "uploads/no-such.png")).toBeNull();
    expect(await mediaLimits(env, reader)).toMatchObject({ types: expect.arrayContaining(["image/png"]) });
  });

  it("uploads as an Editor into the site's own storage", async () => {
    const outcome = await uploadMedia(env, await project("editor@test.invalid"), await actor("editor@test.invalid"), file(PNG), "The river at dusk");
    expect(outcome).toMatchObject({ ok: true, item: { filename: "river.png", alt: "The river at dusk", src: expect.stringMatching(/^https:\/\/site\.test\/media\//) } });
    expect(site.adapter.mediaStore.size).toBe(1);
  });

  it("deletes as the Owner", async () => {
    const item = await seedFile();
    expect(await deleteMedia(env, await project("owner@test.invalid"), await actor("owner@test.invalid"), item.id)).toEqual({ ok: true });
    expect(site.adapter.deleted).toEqual([item.id]);
  });
});

describe("PLANT: roles", () => {
  it("refuses a Reader's upload, and the site hears nothing", async () => {
    const reader = await project("reader@test.invalid");
    expect(await status(async () => uploadMedia(env, reader, await actor("reader@test.invalid"), file(PNG), ""))).toBe(403);
    expect(site.requests.filter((r) => r.startsWith("POST"))).toEqual([]);
  });

  it("refuses an Editor's delete, and the file stays", async () => {
    const item = await seedFile();
    const editor = await project("editor@test.invalid");
    expect(await status(async () => deleteMedia(env, editor, await actor("editor@test.invalid"), item.id))).toBe(403);
    expect(site.adapter.mediaStore.has(item.id)).toBe(true);
    expect(site.requests.filter((r) => r.startsWith("DELETE"))).toEqual([]);
  });

  it("answers 404 to someone the project is not shared with", async () => {
    expect(await status(() => project("stranger@test.invalid"))).toBe(404);
  });

  it("refuses at the routes too: a Reader's upload and an Editor's delete", async () => {
    await seedFile();
    const form = new FormData();
    form.set("file", new File([PNG], "river.png", { type: "image/png" }));
    const upload = new Request(`https://carrel.test/p/${SLUG}/media/api`, { method: "POST", body: form });
    const readerContext = await contextFor("reader@test.invalid");
    expect(await status(() => apiAction({ request: upload, params: { project: SLUG }, context: readerContext } as never))).toBe(403);
    expect(site.requests.filter((r) => r.startsWith("POST"))).toEqual([]);

    const del = new FormData();
    del.set("intent", "delete");
    del.set("id", "uploads/1-river.png");
    del.set("confirm", "delete");
    const request = new Request(`https://carrel.test/p/${SLUG}/media`, { method: "POST", body: del });
    const context = await contextFor("editor@test.invalid");
    expect(await status(() => mediaAction({ request, params: { project: SLUG }, context } as never))).toBe(403);
    expect(site.adapter.mediaStore.size).toBe(1);
  });
});

describe("PLANT: deleting a file a post uses", () => {
  it("is refused by the site's reference check, with the post named, and the file stays", async () => {
    const item = await seedFile();
    await site.adapter.content.saveDraft("river-post", {
      source: `---\ntitle: The river\n---\nIntro.\n\n:::figure{src="${item.url}" alt="The river"}\n:::\n`,
      expectedVersion: null,
      changeId: "c1",
    });
    const owner = await project("owner@test.invalid");
    expect(await mediaDetail(env, owner, item.id)).toMatchObject({ usedBy: [{ id: "river-post", title: "The river", detail: "line 6" }] });

    const outcome = await deleteMedia(env, owner, await actor("owner@test.invalid"), item.id);
    expect(outcome).toMatchObject({ ok: false, usedBy: [{ type: "post", id: "river-post", title: "The river", detail: "line 6" }] });
    expect(!outcome.ok && outcome.message).toContain("The river (line 6)");
    expect(site.adapter.mediaStore.has(item.id)).toBe(true);
    expect(site.adapter.deleted).toEqual([]);
  });

  it("asks before it deletes, then shows the refusal on the page", async () => {
    const item = await seedFile();
    await site.adapter.content.saveDraft("river-post", { source: `# The river\n\n![](${item.url})\n`, expectedVersion: null, changeId: "c1" });
    const post = async (fields: Record<string, string>) => {
      const form = new FormData();
      for (const [k, v] of Object.entries(fields)) form.set(k, v);
      const request = new Request(`https://carrel.test/p/${SLUG}/media`, { method: "POST", body: form });
      return mediaAction({ request, params: { project: SLUG }, context: await contextFor("owner@test.invalid") } as never);
    };
    expect(await post({ intent: "delete", id: item.id })).toEqual({ intent: "delete", needsConfirm: true, id: item.id });
    expect(site.requests.filter((r) => r.startsWith("DELETE"))).toEqual([]);
    expect(await post({ intent: "delete", id: item.id, confirm: "delete" })).toMatchObject({
      intent: "delete",
      ok: false,
      usedBy: [{ id: "river-post", title: "The river" }],
    });
    expect(site.adapter.mediaStore.has(item.id)).toBe(true);
  });
});

describe("PLANT: an upload the site does not accept", () => {
  it("refuses a type the site did not declare before sending anything", async () => {
    const outcome = await uploadMedia(env, await project("editor@test.invalid"), await actor("editor@test.invalid"), file(new TextEncoder().encode("<script>x</script>"), "page.html", "text/html"), "");
    expect(outcome).toMatchObject({ ok: false, message: expect.stringContaining("this site accepts") });
    expect(site.requests.filter((r) => r.startsWith("POST"))).toEqual([]);
  });

  it("refuses a file over the site's limit before sending anything", async () => {
    site = fakeSite(memoryAdapter({ media: { maxBytes: 64, types: ["image/png"] } }));
    vi.stubGlobal("fetch", site.fetch);
    const big = new Uint8Array(65);
    big.set(PNG.subarray(0, 8));
    const outcome = await uploadMedia(env, await project("editor@test.invalid"), await actor("editor@test.invalid"), file(big), "");
    expect(outcome).toMatchObject({ ok: false, message: expect.stringContaining("accepts files up to") });
    expect(site.requests.filter((r) => r.startsWith("POST"))).toEqual([]);
    expect(site.adapter.mediaStore.size).toBe(0);
  });

  it("shows the site API's refusal of bytes that are not their type, and stores nothing", async () => {
    const outcome = await uploadMedia(env, await project("editor@test.invalid"), await actor("editor@test.invalid"), file(new TextEncoder().encode("not a png at all"), "fake.png"), "");
    expect(outcome).toMatchObject({ ok: false, message: expect.stringContaining("The site refused fake.png") });
    expect(site.adapter.mediaStore.size).toBe(0);
  });
});

describe("a site with no media library", () => {
  beforeEach(() => {
    site = fakeSite(memoryAdapter({ media: false }));
    vi.stubGlobal("fetch", site.fetch);
  });

  it("says so on the page, and the editor gets no image tools", async () => {
    const data = (await mediaLoader({ request: new Request(`https://carrel.test/p/${SLUG}/media`), params: { project: SLUG }, context: await contextFor("owner@test.invalid") } as never)) as { unavailable: string | null };
    expect(data.unavailable).toBe("This site has no media library yet.");
    await site.adapter.content.saveDraft("post-one", { source: "# One\n", expectedVersion: null, changeId: "s" });
    const editor = (await editorLoader({ params: { project: SLUG, item: "post-one" }, context: await contextFor("owner@test.invalid") } as never)) as { media: unknown };
    expect(editor.media).toBeNull();
  });
});

describe("the editor's image tools", () => {
  it("are given to an Editor with the site's accepted types, and never to a Reader", async () => {
    await site.adapter.content.saveDraft("post-one", { source: "# One\n", expectedVersion: null, changeId: "s" });
    const load = async (email: string) =>
      (await editorLoader({ params: { project: SLUG, item: "post-one" }, context: await contextFor(email) } as never)) as { media: { endpoint: string; accept: string } | null };
    expect((await load("editor@test.invalid")).media).toEqual({ endpoint: `/p/${SLUG}/media/api`, accept: expect.stringContaining("image/png") });
    expect((await load("reader@test.invalid")).media).toBeNull();
  });

  it("uploads through the endpoint and answers the site's address and where to show it", async () => {
    const form = new FormData();
    form.set("file", new File([PNG], "river.png", { type: "image/png" }));
    const request = new Request(`https://carrel.test/p/${SLUG}/media/api`, { method: "POST", body: form });
    const response = (await apiAction({ request, params: { project: SLUG }, context: await contextFor("editor@test.invalid") } as never)) as Response;
    expect(response.status).toBe(201);
    const body = (await response.json()) as { url: string; src: string };
    expect(body.url).toMatch(/^\/media\/uploads\//);
    expect(body.src).toBe(`${SITE_ORIGIN}${body.url}`);
  });

  it("lists for the picker, and says why when the site cannot be reached", async () => {
    await seedFile();
    const list = (await apiLoader({ request: new Request(`https://carrel.test/p/${SLUG}/media/api?q=river`), params: { project: SLUG }, context: await contextFor("reader@test.invalid") } as never)) as Response;
    expect(((await list.json()) as { items: unknown[] }).items).toHaveLength(1);
    const offline = { ...env, SITE_DUSTINEDWARDS_KEY: "" };
    const answer = (await apiLoader({ request: new Request(`https://carrel.test/p/${SLUG}/media/api`), params: { project: SLUG }, context: await contextFor("reader@test.invalid", offline) } as never)) as Response;
    expect(await answer.json()).toMatchObject({ items: [], error: expect.stringContaining("not connected") });
  });

  it("inserts the site's own figure, with the alt text escaped", () => {
    expect(figureMarkup("dustinedwards", "/media/a.png", ' The "river" ')).toBe(':::figure{src="/media/a.png" alt="The &quot;river&quot;"}\n:::');
    expect(figureMarkup("some-other-site", "/media/a.png", "A [river]")).toBe("![A river](/media/a.png)");
  });
});

describe("the image policy", () => {
  it("loads images from the configured sites, and drops anything that is not a plain https origin", () => {
    const policy = appPolicy("n", ["https://site.test", "https://evil.test; script-src *", "http://plain.test"]);
    expect(policy).toContain("img-src 'self' data: https://site.test;");
    expect(policy).not.toContain("evil.test");
    expect(policy).not.toContain("plain.test");
  });
});

describe("health", () => {
  it("runs the media conformance against a site with media, and never stores or deletes a file", async () => {
    const existing = await seedFile();
    const box = { sent: [] as unknown[] };
    const EMAIL = { send: async (m: unknown) => (box.sent.push(m), { messageId: "m" }) } as unknown as SendEmail;
    const fetcher = (async (input: RequestInfo | URL, init?: RequestInit) => {
      const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
      return url.includes("cloudflareaccess") ? Response.json({ keys: [{ kid: "k" }] }) : site.fetch(url, init);
    }) as unknown as Parameters<typeof runHealth>[1];
    const { results } = await runHealth({ ...env, EMAIL }, fetcher);
    expect(results.find((r) => r.name === "site-dustinedwards")).toMatchObject({ ok: true });
    expect(site.requests).toEqual(expect.arrayContaining(["GET /api/carrel/v1/media", "DELETE /api/carrel/v1/media/carrel-conformance-probe%2Fno-such-file.png", "POST /api/carrel/v1/media"]));
    expect([...site.adapter.mediaStore.keys()]).toEqual([existing.id]);
    expect(site.adapter.deleted).toEqual([]);
  });
});

test/csp.test.ts.source:
// The Content Security Policy, required before the editor ships: every page carries a per-request
// nonce policy with no unsafe script source, the preview alone may be framed and only by Carrel, and
// the site's page inside it runs sandboxed.

import { createLocalJWKSet, exportJWK, generateKeyPair, SignJWT, type JWK } from "jose";
import { beforeAll, beforeEach, describe, expect, it } from "vitest";

import { previewPolicy, previewResponse, withSiteBase } from "~/lib/preview.server";

import { appPolicy, newNonce, withPolicy } from "../workers/csp";
import { gate } from "../workers/gate";

import { addPerson, resetDb, testEnv } from "./env";

describe("the app policy", () => {
  it("allows scripts only by this render's nonce, never inline or eval", () => {
    const policy = appPolicy("abc123");
    const scripts = policy.split("; ").find((d) => d.startsWith("script-src "))!;
    expect(scripts).toBe("script-src 'nonce-abc123' 'strict-dynamic'");
    expect(policy).not.toMatch(/'unsafe-eval'/);
    expect(policy).toContain("object-src 'none'");
    expect(policy).toContain("base-uri 'none'");
    expect(policy).toContain("frame-ancestors 'none'");
    expect(policy).toContain("frame-src 'self'");
  });

  it("stays strict for Cloudflare's Web Analytics beacon: no host in script-src, connect-src is 'self'", () => {
    const directives = appPolicy("abc123").split("; ");
    const scripts = directives.find((d) => d.startsWith("script-src "))!;
    const connect = directives.find((d) => d.startsWith("connect-src "))!;
    const why =
      "Carrel is private and its hosts are excluded from Web Analytics in the Cloudflare dashboard; do not loosen the policy for the beacon (static.cloudflareinsights.com).";
    // Only the nonce and 'strict-dynamic' may appear: no scheme, no host, no wildcard.
    expect(scripts.split(" ").slice(1), why).toEqual(["'nonce-abc123'", "'strict-dynamic'"]);
    expect(connect, why).toBe("connect-src 'self'");
  });

  it("mints a different nonce every time", () => {
    const nonces = new Set(Array.from({ length: 50 }, newNonce));
    expect(nonces.size).toBe(50);
  });

  it("PLANT: a page without a policy gets one; a route's own policy is kept", () => {
    const page = withPolicy(new Response("<html></html>"), "n1");
    expect(page.headers.get("Content-Security-Policy")).toBe(appPolicy("n1"));
    const preview = withPolicy(previewResponse("<html><head></head></html>", "https://site.test"), "n1");
    expect(preview.headers.get("Content-Security-Policy")).toBe(previewPolicy("https://site.test"));
  });

  it("adds the policy to a response whose headers are immutable", () => {
    const redirect = Response.redirect("https://carrel.test/", 302);
    expect(withPolicy(redirect, "n2").headers.get("Content-Security-Policy")).toBe(appPolicy("n2"));
  });
});

describe("the preview", () => {
  it("runs the site's page sandboxed: no script, no forms, only the site's styles and images", () => {
    const policy = previewPolicy("https://site.test");
    expect(policy.split("; ")[0]).toBe("sandbox");
    expect(policy).toContain("default-src 'none'");
    expect(policy).toContain("script-src 'none'");
    expect(policy).toContain("form-action 'none'");
    expect(policy).toContain("style-src https://site.test 'unsafe-inline'");
    expect(policy).toContain("frame-ancestors 'self'");
  });

  it("resolves the page's relative URLs against the site and drops the page's own <base>", () => {
    const html = withSiteBase('<html><head lang="en"><base href="https://evil.test/"><link href="/a.css"></head></html>', "https://site.test");
    expect(html).toBe('<html><head lang="en"><base href="https://site.test/"><link href="/a.css"></head></html>');
    expect(withSiteBase("<p>no head</p>", "https://site.test")).toBe('<base href="https://site.test/"><p>no head</p>');
  });
});

describe("framing through the gate", () => {
  let keys: ReturnType<typeof createLocalJWKSet>;
  let token: string;

  beforeAll(async () => {
    const pair = await generateKeyPair("RS256", { extractable: true });
    const jwk: JWK = { ...(await exportJWK(pair.publicKey)), kid: "test", alg: "RS256" };
    keys = createLocalJWKSet({ keys: [jwk] });
    token = await new SignJWT({ email: "owner@test.invalid" })
      .setProtectedHeader({ alg: "RS256", kid: "test" })
      .setIssuer(testEnv.ACCESS_TEAM_DOMAIN)
      .setAudience(testEnv.ACCESS_AUD)
      .setIssuedAt()
      .setExpirationTime("5m")
      .sign(pair.privateKey);
  });

  beforeEach(async () => {
    await resetDb();
    await addPerson("owner@test.invalid", { owner: true });
  });

  /** A verified Owner's request, so the test reads only what the gate does to the rendered response. */
  function through(render: () => Response) {
    const request = new Request("https://carrel.test/", { headers: { "Cf-Access-Jwt-Assertion": token } });
    return gate(request, testEnv, async () => render(), keys);
  }

  it("PLANT: denies framing of every page by default", async () => {
    const response = await through(() => new Response("page"));
    expect(response.headers.get("X-Frame-Options")).toBe("DENY");
  });

  it("lets the preview be framed by Carrel alone", async () => {
    const response = await through(() => previewResponse("<html><head></head></html>", "https://site.test"));
    expect(response.headers.get("X-Frame-Options")).toBe("SAMEORIGIN");
  });

  it("cannot be loosened by a route asking for ALLOW-FROM or anything else", async () => {
    const response = await through(() => new Response("page", { headers: { "X-Frame-Options": "ALLOW-FROM https://evil.test" } }));
    expect(response.headers.get("X-Frame-Options")).toBe("DENY");
  });
});

test/books.test.ts.source:
// Books through Carrel's service layer, against the fake novels repository: who may open, save and
// export; a save that commits with the version it expects and records who wrote what; the checks
// that run on save and never stop it; and export held while a flag is open.

import { beforeEach, describe, expect, it } from "vitest";

import {
  assembleBook,
  authorshipRecord,
  authorshipReport,
  checkDraft,
  createBook,
  dismissFinding,
  exportGate,
  listFiles,
  listFindings,
  refreshBook,
  requireBookProject,
  saveBookFile,
  wordDelta,
} from "~/lib/books.server";
import { autosave, readDraft } from "~/lib/content.server";
import { requireSiteProject } from "~/lib/projects.server";

import { addBook, addPerson, addProject, resetDb, share, testEnv } from "./env";
import { BASELINE, PLANT } from "./fixtures/voice";
import { fakeNovels } from "./novels";
import { viewerFor } from "./site";

const SLUG = "test-book";

const WADE = "---\nname: Wade Pruitt\naliases: [Wade]\nborn: 1996-02-11\n---\nRanch hand.\n";
const PLACE = "---\nname: Harlan place\n---\n";
const RULE = "---\nname: No phones past the ridge\nforbidden: [phone rang]\n---\n";
const HEADER = "---\npov: Wade\ndate: 2024-04-12\nlocation: Harlan place\ncharacters: [Wade]\ngoal: get in\nconflict: the lock\noutcome: he opens it\n---\n\n";

function seedRepo(extra: Record<string, string> = {}) {
  return fakeNovels({
    [`${SLUG}/book.md`]: "---\ntitle: The Test Book\nauthor: Test Author\n---\n",
    [`${SLUG}/bible/characters/wade.md`]: WADE,
    [`${SLUG}/bible/places/harlan-place.md`]: PLACE,
    [`${SLUG}/bible/rules/phones.md`]: RULE,
    [`${SLUG}/chapters/01-arrival/01-the-gate.md`]: `${HEADER}Wade opened the gate.\n`,
    [`${SLUG}/chapters/01-arrival/02-supper.md`]: HEADER.replace("2024-04-12", "2024-04-12 19:00") + "They ate at the kitchen table.\n",
    [`${SLUG}/outline/plan.md`]: "# Plan\n",
    [`${SLUG}/build/book.epub`]: "ignored",
    [`${SLUG}/notes.txt`]: "ignored",
    "shared/checks/ai-habits.md": "---\nwords: [suddenly]\n---\n",
    ...extra,
  });
}

async function refusal(promise: Promise<unknown>): Promise<number> {
  try {
    await promise;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
  throw new Error("expected a refusal, and the call succeeded");
}

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  await addPerson("stranger@test.invalid");
  const id = await addBook(SLUG);
  await share(id, editor, "editor");
  await share(id, reader, "reader");
});

async function as(email: string, action: "read" | "edit" | "publish" = "read") {
  const viewer = await viewerFor(email);
  return { viewer, project: await requireBookProject(testEnv.DB, viewer, SLUG, action) };
}

describe("opening a book", () => {
  it("PLANT: a non-member, a missing book, and a site all answer 404", async () => {
    const stranger = await viewerFor("stranger@test.invalid");
    const owner = await viewerFor("owner@test.invalid");
    await addProject("a-site", "dustinedwards");
    expect(await refusal(requireBookProject(testEnv.DB, stranger, SLUG, "read"))).toBe(404);
    expect(await refusal(requireBookProject(testEnv.DB, owner, "no-such-book", "read"))).toBe(404);
    expect(await refusal(requireBookProject(testEnv.DB, owner, "a-site", "read"))).toBe(404);
    // And the other way: a book is not a site.
    expect(await refusal(requireSiteProject(testEnv.DB, owner, SLUG, "read"))).toBe(404);
  });

  it("PLANT: a Reader asking to edit is refused 403", async () => {
    const reader = await viewerFor("reader@test.invalid");
    expect(await refusal(requireBookProject(testEnv.DB, reader, SLUG, "edit"))).toBe(403);
  });

  it("creates a book for the Owner only, with a folder name the layout allows", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const editor = await viewerFor("editor@test.invalid");
    expect(await refusal(createBook(testEnv.DB, editor, { name: "Mine", folder: "mine" }))).toBe(403);
    expect(await createBook(testEnv.DB, owner, { name: "Paluxy Portal", folder: "paluxy-portal" })).toEqual({ ok: true, slug: "paluxy-portal" });
    expect((await createBook(testEnv.DB, owner, { name: "Again", folder: "paluxy-portal" })).ok).toBe(false);
    expect((await createBook(testEnv.DB, owner, { name: "Bad", folder: "../etc" })).ok).toBe(false);
    expect((await createBook(testEnv.DB, owner, { name: "Shared", folder: "shared" })).ok).toBe(false);
  });
});

describe("refresh from Git", () => {
  it("indexes the book's Markdown files by kind, skips build/ and other files, and reads shared/", async () => {
    const gh = seedRepo();
    const { project } = await as("reader@test.invalid");
    const result = await refreshBook(testEnv.DB, gh.repo, project);
    expect(result).toMatchObject({ files: 7, read: 7, removed: 0, shared: 1, more: false });
    const files = await listFiles(testEnv.DB, project);
    expect(files.map((f) => [f.path, f.kind])).toEqual([
      ["bible/characters/wade.md", "character"],
      ["bible/places/harlan-place.md", "place"],
      ["bible/rules/phones.md", "rule"],
      ["book.md", "book"],
      ["chapters/01-arrival/01-the-gate.md", "scene"],
      ["chapters/01-arrival/02-supper.md", "scene"],
      ["outline/plan.md", "outline"],
    ]);
    // A clean book has nothing flagged.
    expect(await listFindings(testEnv.DB, project)).toEqual([]);
  });

  it("reads again only what changed, and drops what Git no longer has", async () => {
    const gh = seedRepo();
    const { project } = await as("reader@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    gh.files.delete(`${SLUG}/outline/plan.md`);
    await gh.commitElsewhere(`${SLUG}/chapters/01-arrival/02-supper.md`, `${HEADER}Suddenly they ate.\n`);
    const before = gh.requests.length;
    expect(await refreshBook(testEnv.DB, gh.repo, project)).toMatchObject({ read: 1, removed: 1, shared: 0 });
    expect(gh.requests.slice(before).filter((r) => r.includes("/contents/"))).toEqual([
      `GET /repos/DrDustinEdwards/novels/contents/${SLUG}/chapters/01-arrival/02-supper.md`,
    ]);
    // The checks ran on what changed outside Carrel, with the book's own habits list.
    expect((await listFindings(testEnv.DB, project)).map((f) => f.excerpt)).toEqual(["Suddenly"]);
  });
});

describe("saving", () => {
  it("PLANT: a Reader cannot autosave or save, and Git hears nothing", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("reader@test.invalid");
    const path = "chapters/01-arrival/01-the-gate.md";
    expect(await refusal(autosave(testEnv.DB, project, viewer, path, { source: "x", baseVersion: null }))).toBe(403);
    expect(await refusal(saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: "x", expectedVersion: null }))).toBe(403);
    expect(gh.requests.filter((r) => r.startsWith("PUT"))).toEqual([]);
  });

  it("PLANT: a path outside the layout is refused before Git is asked", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    for (const path of ["../other-book/book.md", "build/x.md", "chapters/one/two.md", "notes.txt", "chapters/01-a/01-b.md/../../x.md"]) {
      expect(await refusal(saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: "x", expectedVersion: null }))).toBe(404);
    }
    expect(gh.requests).toEqual([]);
  });

  it("commits as the person with a change id and no AI trailer, records authorship, clears the draft", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("editor@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const path = "chapters/01-arrival/01-the-gate.md";
    const file = (await listFiles(testEnv.DB, project)).find((f) => f.path === path)!;
    await autosave(testEnv.DB, project, viewer, path, { source: "draft", baseVersion: file.sha });

    const result = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, {
      source: `${HEADER}Wade opened the old gate slowly.\n`,
      expectedVersion: file.sha,
    });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(gh.commits).toHaveLength(1);
    expect(gh.commits[0]).toMatchObject({ path: `${SLUG}/${path}`, author: { name: "editor", email: "editor@test.invalid" } });
    expect(gh.commits[0]!.message).toBe(`Save ${SLUG}/${path}\n\nCarrel-Change: ${result.changeId}`);
    expect(gh.commits[0]!.message).not.toMatch(/claude|anthropic|co-authored/i);
    expect(await readDraft(testEnv.DB, project, viewer, path)).toBeNull();

    const record = await authorshipRecord(testEnv.DB, project);
    expect(record).toMatchObject([{ id: result.changeId, path, who: "editor", client: null, wordsAdded: 2, wordsRemoved: 0, commit: result.commit }]);
    const report = authorshipReport(project, record, new Date("2026-09-27T00:00:00Z"));
    expect(report).toContain("| editor | 1 | 2 | 0 |");
    expect(report).toContain(`| editor | ${path} | 2 | 0 | ${result.commit.slice(0, 7)} |`);
  });

  it("PLANT: a stale expected version is refused as a conflict, and the draft is kept", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const path = "chapters/01-arrival/01-the-gate.md";
    const opened = (await listFiles(testEnv.DB, project)).find((f) => f.path === path)!.sha;
    await autosave(testEnv.DB, project, viewer, path, { source: "my words", baseVersion: opened });
    await gh.commitElsewhere(`${SLUG}/${path}`, `${HEADER}Someone else's words.\n`);

    const result = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: "my words", expectedVersion: opened });
    expect(result).toMatchObject({ ok: false, reason: "conflict" });
    expect(gh.files.get(`${SLUG}/${path}`)!.source).toBe(`${HEADER}Someone else's words.\n`);
    expect((await readDraft(testEnv.DB, project, viewer, path))?.source).toBe("my words");
    expect(await authorshipRecord(testEnv.DB, project)).toEqual([]);
  });

  it("creates a new scene only where no file exists", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    const path = "chapters/02-letters/01-morning.md";
    const created = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: `${HEADER.replace("2024-04-12", "2024-04-13")}Morning.\n`, expectedVersion: null });
    expect(created.ok).toBe(true);
    const again = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: "overwrite", expectedVersion: null });
    expect(again).toMatchObject({ ok: false, reason: "conflict" });
  });
});

describe("checks on save", () => {
  it("PLANT: a flagged scene still saves; the flags come back and are recorded", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const path = "chapters/01-arrival/03-late.md";
    const source = HEADER.replace("characters: [Wade]", "characters: [Wade, Tobias]").replace("2024-04-12", "2024-04-11") + "Then the phone rang. It's not just a farm, it's a promise.\n";
    const result = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source, expectedVersion: null });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(gh.files.get(`${SLUG}/${path}`)!.source).toBe(source);
    expect(result.findings.map((f) => f.check).sort()).toEqual(["ai-habits", "continuity", "timeline", "world-rules"]);
    expect((await listFindings(testEnv.DB, project, { path })).map((f) => f.check).sort()).toEqual(["ai-habits", "continuity", "timeline", "world-rules"]);
  });

  it("PLANT: the voice check flags another author's passage once shared/voice/ holds Dustin's", async () => {
    const voice = Object.fromEntries(BASELINE.map((text, i) => [`shared/voice/passage-${i + 1}.md`, text]));
    const gh = seedRepo({ ...voice, "shared/voice/README.md": "Put your passages here." });
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const result = await saveBookFile(testEnv.DB, gh.repo, project, viewer, "chapters/01-arrival/03-tea.md", {
      source: HEADER.replace("2024-04-12", "2024-04-13") + PLANT,
      expectedVersion: null,
    });
    expect(result.ok && result.findings.map((f) => f.check)).toEqual(["voice"]);
  });

  it("fixing the text clears the flag; saving a bible entry rechecks every scene", async () => {
    const gh = seedRepo();
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const path = "chapters/01-arrival/03-late.md";
    const withTobias = HEADER.replace("characters: [Wade]", "characters: [Wade, Tobias]").replace("2024-04-12", "2024-04-13") + "Quiet.\n";
    const saved = await saveBookFile(testEnv.DB, gh.repo, project, viewer, path, { source: withTobias, expectedVersion: null });
    expect((await listFindings(testEnv.DB, project, { status: "open" })).map((f) => f.excerpt)).toEqual(["Tobias"]);

    // Adding Tobias to the bible resolves the scene's flag without touching the scene.
    const bible = await saveBookFile(testEnv.DB, gh.repo, project, viewer, "bible/characters/tobias.md", { source: "---\nname: Tobias\n---\n", expectedVersion: null });
    expect(bible.ok && saved.ok).toBe(true);
    expect(await listFindings(testEnv.DB, project)).toEqual([]);
  });

  it("checks a draft without saving or recording anything", async () => {
    const gh = seedRepo();
    const { project } = await as("reader@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const found = await checkDraft(testEnv.DB, project, "chapters/01-arrival/01-the-gate.md", `${HEADER}A tapestry.\n`);
    expect(found.map((f) => f.excerpt)).toEqual(["tapestry"]);
    expect(await listFindings(testEnv.DB, project)).toEqual([]);
    expect(gh.requests.filter((r) => r.startsWith("PUT"))).toEqual([]);
  });
});

describe("dismissing flags and exporting", () => {
  async function flagged() {
    const gh = seedRepo();
    const owner = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, owner.project);
    await saveBookFile(testEnv.DB, gh.repo, owner.project, owner.viewer, "chapters/01-arrival/03-late.md", {
      source: HEADER.replace("2024-04-12", "2024-04-13") + "A tapestry. Another tapestry.\n",
      expectedVersion: null,
    });
    return { gh, owner };
  }

  it("PLANT: export is refused while a flag is open, and to anyone but the Owner", async () => {
    const { owner } = await flagged();
    expect(await exportGate(testEnv.DB, owner.project)).toMatchObject({ ok: false, open: 2 });
    const editor = await as("editor@test.invalid");
    expect(await refusal(exportGate(testEnv.DB, editor.project))).toBe(403);
    expect(await refusal(assembleBook(testEnv.DB, editor.project, editor.viewer))).toBe(403);
  });

  it("PLANT: an Editor cannot dismiss a flag; the Owner can, and a dismissal survives the next save", async () => {
    const { gh, owner } = await flagged();
    const editor = await as("editor@test.invalid");
    const [first, second] = await listFindings(testEnv.DB, owner.project);
    expect(await refusal(dismissFinding(testEnv.DB, editor.project, editor.viewer, first!.id))).toBe(403);

    await dismissFinding(testEnv.DB, owner.project, owner.viewer, first!.id);
    await dismissFinding(testEnv.DB, owner.project, owner.viewer, second!.id);
    expect(await exportGate(testEnv.DB, owner.project)).toEqual({ ok: true });

    // Saving again with the same words keeps both dismissed; a new tapestry is a new flag.
    const path = "chapters/01-arrival/03-late.md";
    const current = gh.files.get(`${SLUG}/${path}`)!;
    await saveBookFile(testEnv.DB, gh.repo, owner.project, owner.viewer, path, { source: `${current.source}A third tapestry.\n`, expectedVersion: current.sha });
    const all = await listFindings(testEnv.DB, owner.project);
    expect(all.map((f) => f.status).sort()).toEqual(["dismissed", "dismissed", "open"]);
  });

  it("a dismissal in another book cannot be reached by id", async () => {
    const { owner } = await flagged();
    const [finding] = await listFindings(testEnv.DB, owner.project);
    await addBook("other-book");
    const other = await requireBookProject(testEnv.DB, owner.viewer, "other-book", "publish");
    expect(await refusal(dismissFinding(testEnv.DB, other, owner.viewer, finding!.id))).toBe(404);
  });

  it("assembles the book in reading order with its title and author from book.md", async () => {
    const gh = seedRepo({ [`${SLUG}/chapters/10-late/01-end.md`]: `${HEADER.replace("2024-04-12", "2024-05-01")}The end.\n` });
    const { viewer, project } = await as("owner@test.invalid");
    await refreshBook(testEnv.DB, gh.repo, project);
    const book = await assembleBook(testEnv.DB, project, viewer);
    expect(book.title).toBe("The Test Book");
    expect(book.author).toBe("Test Author");
    expect(book.chapters.map((c) => [c.title, c.scenes.map((s) => s.body)])).toEqual([
      ["Arrival", ["Wade opened the gate.", "They ate at the kitchen table."]],
      ["Late", ["The end."]],
    ]);
  });
});

describe("word counts for the authorship record", () => {
  it("counts a changed word once each way and a moved word not at all", () => {
    expect(wordDelta("the cat sat", "the dog sat")).toEqual({ added: 1, removed: 1 });
    expect(wordDelta("a b c", "c b a")).toEqual({ added: 0, removed: 0 });
    expect(wordDelta(null, "---\ntitle: x\n---\none two")).toEqual({ added: 2, removed: 0 });
  });
});

test/mcp-followups.test.ts.source:
// The follow-ups after the overnight merges: books through MCP, draft_social_post, a reviewer's flag
// that a recheck must not withdraw, and export refused while an import marker is left in a book.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { exportGate, listFindings, refreshBook, requireBookProject, saveBookFile, type BookProject } from "~/lib/books.server";
import { autosave, readDraft } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import type { Viewer } from "~/lib/people.server";
import { createAccount, recordPublication, setSwitches } from "~/lib/social/queue.server";
import { action as fileAction, loader as fileLoader } from "~/routes/book.file";

import { addBook, addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectAs } from "./mcp-client";
import { fakeNovels } from "./novels";
import { viewerFor } from "./site";

const SLUG = "test-book";
const HEADER = "---\npov: Wade\ndate: 2024-04-12\nlocation: Harlan place\ncharacters: [Wade]\ngoal: g\nconflict: c\noutcome: o\n---\n\n";
const SCENE = "chapters/01-arrival/01-the-gate.md";

let gh: ReturnType<typeof fakeNovels>;

async function readDraftOnly(project: BookProject, viewer: Viewer, path: string) {
  return (await readDraft(testEnv.DB, project, viewer, path))?.source;
}

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  const reviewer = await addPerson("reviewer@test.invalid", { reviewer: true });
  const id = await addBook(SLUG);
  await share(id, editor, "editor");
  await share(id, reader, "reader");
  await share(id, reviewer, "reader");
  gh = fakeNovels({
    [`${SLUG}/bible/characters/wade.md`]: "---\nname: Wade\n---\n",
    [`${SLUG}/bible/places/harlan-place.md`]: "---\nname: Harlan place\n---\n",
    [`${SLUG}/${SCENE}`]: `${HEADER}Wade opened the gate.\n`,
  });
  const owner = await viewerFor("owner@test.invalid");
  await refreshBook(testEnv.DB, gh.repo, await requireBookProject(testEnv.DB, owner, SLUG, "read"));
});

async function connect(email: string, client = "Claude") {
  const ai = await connectAs(email, client);
  return ai.call;
}

describe("books through MCP", () => {
  it("lists a book's files with each scene's header, and reads a file with its version", async () => {
    const call = await connect("reader@test.invalid");
    const list = await call("list_book_files", { project: SLUG });
    expect(list.structuredContent).toMatchObject({ files: expect.arrayContaining([{ path: SCENE, kind: "scene", words: 4, header: expect.objectContaining({ pov: "Wade" }), openFlags: 0 }]) });
    const read = await call("read_book_file", { project: SLUG, path: SCENE });
    expect(read.structuredContent).toMatchObject({ path: SCENE, source: `${HEADER}Wade opened the gate.\n`, version: gh.files.get(`${SLUG}/${SCENE}`)!.sha });
  });

  it("PLANT: a stranger's session, and a site's slug, reach no book", async () => {
    await addPerson("stranger@test.invalid");
    expect(await (await connect("stranger@test.invalid"))("list_book_files", { project: SLUG })).toMatchObject({ isError: true });
    await addProject("a-site", "dustinedwards");
    expect(await (await connect("owner@test.invalid"))("list_book_files", { project: "a-site" })).toMatchObject({ isError: true });
  });

  it("runs the checks on text without saving or recording anything", async () => {
    const call = await connect("reader@test.invalid");
    const result = await call("check_book_text", { project: SLUG, path: SCENE, source: `${HEADER}A tapestry.\n` });
    expect(result.structuredContent).toMatchObject({ findings: [{ check: "ai-habits", excerpt: "tapestry" }] });
    const owner = await viewerFor("owner@test.invalid");
    expect(await listFindings(testEnv.DB, await requireBookProject(testEnv.DB, owner, SLUG, "read"))).toEqual([]);
  });

  it("saves an AI draft beside the person's, never over it and never to Git", async () => {
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireBookProject(testEnv.DB, owner, SLUG, "read");
    await autosave(testEnv.DB, project, owner, SCENE, { source: "Dustin's own draft.", baseVersion: null });

    const saved = await (await connect("owner@test.invalid"))("save_book_draft", { project: SLUG, path: SCENE, source: `${HEADER}An AI version.\n`, note: "Tighter." });
    expect(saved.structuredContent).toMatchObject({ saved: true, basedOnVersion: gh.files.get(`${SLUG}/${SCENE}`)!.sha });
    expect(await readDraftOnly(project, owner, SCENE)).toBe("Dustin's own draft.");
    expect(gh.commits).toEqual([]);
  });

  it("PLANT: a reviewer's and a Reader's sessions cannot save a book draft", async () => {
    expect(await (await connect("reviewer@test.invalid"))("save_book_draft", { project: SLUG, path: SCENE, source: "x" })).toMatchObject({
      isError: true,
      content: [{ text: "A reviewer flags; it does not write text. Use add_book_finding." }],
    });
    expect(await (await connect("reader@test.invalid"))("save_book_draft", { project: SLUG, path: SCENE, source: "x" })).toMatchObject({ isError: true });
  });

  it("PLANT: a reviewer's flag on a book file survives the recheck a save runs, and holds export", async () => {
    const reviewer = await connect("reviewer@test.invalid", "Grok Build");
    const flagged = await reviewer("add_book_finding", { project: SLUG, path: SCENE, message: "Wade could not see the gate from the road.", excerpt: "opened the gate" });
    expect(flagged.structuredContent).toMatchObject({ flagged: true, alreadyFlagged: false });

    const owner = await viewerFor("owner@test.invalid");
    const project = await requireBookProject(testEnv.DB, owner, SLUG, "publish");
    const current = gh.files.get(`${SLUG}/${SCENE}`)!;
    const saved = await saveBookFile(testEnv.DB, gh.repo, project, owner, SCENE, { source: `${HEADER}Wade opened the old gate.\n`, expectedVersion: current.sha });
    expect(saved.ok).toBe(true);
    expect((await listFindings(testEnv.DB, project, { path: SCENE })).map((f) => [f.check, f.status])).toEqual([["review", "open"]]);
    expect(await exportGate(testEnv.DB, project)).toMatchObject({ ok: false, open: 1 });
  });

  it("PLANT: a flag on a path outside the layout is refused", async () => {
    expect(await (await connect("reviewer@test.invalid"))("add_book_finding", { project: SLUG, path: "../x.md", message: "m" })).toMatchObject({ isError: true });
  });
});

describe("AI drafts in the book editor", () => {
  it("shows them beside the text, and Use as my draft makes one the working copy", async () => {
    await (await connect("owner@test.invalid"))("save_book_draft", { project: SLUG, path: SCENE, source: `${HEADER}An AI version.\n` });
    vi.stubGlobal("fetch", gh.fetch);
    const context = new RouterContextProvider();
    context.set(cloudflareContext, { env: testEnv, ctx: {} as ExecutionContext });
    context.set(viewerContext, await viewerFor("owner@test.invalid"));
    context.set(nonceContext, "n");
    const params = { project: SLUG, "*": SCENE };
    const data = (await fileLoader({ request: new Request("https://carrel.test/"), params, context } as never)) as Awaited<ReturnType<typeof fileLoader>>;
    expect(data.aiDrafts).toMatchObject([{ client: "Claude", source: `${HEADER}An AI version.\n` }]);

    const body = new FormData();
    body.set("intent", "use-ai-draft");
    body.set("draft", String(data.aiDrafts[0]!.id));
    expect(await fileAction({ request: new Request("https://carrel.test/", { method: "POST", body }), params, context } as never)).toEqual({ intent: "use-ai-draft", used: data.aiDrafts[0]!.id });
    const owner = await viewerFor("owner@test.invalid");
    expect(await readDraftOnly(await requireBookProject(testEnv.DB, owner, SLUG, "read"), owner, SCENE)).toBe(`${HEADER}An AI version.\n`);
  });
});

describe("export refuses a book with import markers", () => {
  it("PLANT: names each file still holding a marker; clean, it passes", async () => {
    await gh.commitElsewhere(`${SLUG}/chapters/01-arrival/02-letter.md`, `${HEADER}Before.\n\n<!-- import: table: A table was not converted. -->\n\nAfter.\n`);
    const owner = await viewerFor("owner@test.invalid");
    const project = await requireBookProject(testEnv.DB, owner, SLUG, "publish");
    await refreshBook(testEnv.DB, gh.repo, project);
    const held = await exportGate(testEnv.DB, project);
    expect(held).toMatchObject({ ok: false });
    expect(held.ok || held.message).toBe(
      "1 file still holds an <!-- import: ... --> marker from the Word import: chapters/01-arrival/02-letter.md. Fix the text there and delete each marker before exporting.",
    );
    await gh.commitElsewhere(`${SLUG}/chapters/01-arrival/02-letter.md`, `${HEADER}Before.\n\nAfter.\n`);
    await refreshBook(testEnv.DB, gh.repo, project);
    expect(await exportGate(testEnv.DB, project)).toEqual({ ok: true });
  });
});

describe("draft_social_post", () => {
  async function socialAccount() {
    const projectId = await addProject("germomics", "dustinedwards");
    const owner = await viewerFor("owner@test.invalid");
    await createAccount(testEnv.DB, owner, { key: "germomics-bluesky", name: "Germomics", platform: "bluesky", kind: "brand", handle: "g.bsky.social", projectId });
    const row = await testEnv.DB.prepare("SELECT id FROM social_accounts").first<{ id: number }>();
    await setSwitches(testEnv.DB, owner, row!.id, { enabled: true });
    await recordPublication(testEnv.DB, projectId, { id: "ep-1", title: "Episode 1", url: "https://site.test/ep-1", summary: "" });
    return (await testEnv.DB.prepare("SELECT id FROM social_events").first<{ id: number }>())!.id;
  }

  it("stores the Owner's session's draft by event id, credited to the client", async () => {
    const eventId = await socialAccount();
    const result = await (await connect("owner@test.invalid", "Claude Code"))("draft_social_post", { event_id: eventId, text: "Episode 1 is out: https://site.test/ep-1" });
    expect(result.structuredContent).toMatchObject({ stored: true });
    expect(await testEnv.DB.prepare("SELECT source, status, created_by FROM social_posts").first()).toEqual({ source: "predrafted", status: "drafted", created_by: "Claude Code" });
  });

  it("stores by account, project and item too", async () => {
    await socialAccount();
    const result = await (await connect("owner@test.invalid"))("draft_social_post", { account: "germomics-bluesky", project: "germomics", item: "ep-2", text: "Episode 2." });
    expect(result.structuredContent).toMatchObject({ stored: true });
  });

  it("PLANT: an Editor's or a reviewer's session cannot draft social posts", async () => {
    const eventId = await socialAccount();
    for (const email of ["editor@test.invalid", "reviewer@test.invalid"]) {
      expect(await (await connect(email))("draft_social_post", { event_id: eventId, text: "x" })).toMatchObject({
        isError: true,
        content: [{ text: "Social posts are Dustin's: only his own sessions may draft them." }],
      });
    }
    expect(await testEnv.DB.prepare("SELECT COUNT(*) AS n FROM social_posts").first()).toEqual({ n: 0 });
  });
});

test/bulk.test.ts.source:
// Bulk actions on the posts list: delete (the Owner's alone), tag and duplicate. Each post is its own
// write, one failing never stops the rest, every outcome is said, and every write the site carried out
// has its authorship row. The refusals (a role, a stale version, a site with no delete) are checked
// to leave the site and the record as they were.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { VersionConflictError } from "@dustinedwards/site-api";

import { bulkApply, cleanTag, MAX_BULK } from "~/lib/bulk.server";
import { autosave, contentDeleteOffered, deleteFromSite, writeToSite } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { requireSiteProject } from "~/lib/projects.server";
import { action as bulkAction } from "~/routes/project.bulk";
import { memoryAdapter } from "@dustinedwards/site-api/testing";

import { addPerson, addProject, resetDb, share, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
let projectId: number;
type Site = ReturnType<typeof fakeSite<ReturnType<typeof memoryAdapter>>>;
let site: Site;
let env: Env;

const POST = (title: string, slug: string, tags: string, body = "Body.") => `---\ntitle: "${title}"\nslug: ${slug}\ndate: 2026-10-01\ntags: ${tags}\ndraft: true\nweird_key: some value: with a colon\n---\n\n${body}\n`;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const reader = await addPerson("reader@test.invalid");
  projectId = await addProject(SLUG, "dustinedwards");
  await share(projectId, editor, "editor");
  await share(projectId, reader, "reader");
  start(fakeSite());
});

function start(next: Site) {
  site = next;
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
}

async function as(email: string, action: "read" | "edit" | "publish" = "read") {
  const viewer = await viewerFor(email);
  return { viewer, project: await requireSiteProject(testEnv.DB, viewer, SLUG, action) };
}

/** A post on the site, written by the Owner; `live` publishes it. */
async function seed(id: string, source: string, live = false) {
  const { viewer, project } = await as("owner@test.invalid", "publish");
  const saved = await writeToSite(env, project, viewer, id, { action: "save", source, expectedVersion: null }, site.fetch);
  if (!saved.ok) throw new Error(saved.message);
  if (live) {
    const published = await writeToSite(env, project, viewer, id, { action: "publish", expectedVersion: saved.version }, site.fetch);
    if (!published.ok) throw new Error(published.message);
  }
}

const sourceOf = (id: string) => site.adapter.store.get(id)?.doc.source;
const rows = async () => (await testEnv.DB.prepare("SELECT action, item_id AS itemId, version_before AS vb, version_after AS va, person_id AS who FROM changes ORDER BY created_at, rowid").all<{ action: string; itemId: string; vb: string | null; va: string | null; who: number }>()).results;
const writes = () => site.requests.filter((r) => !r.startsWith("GET"));

async function refusal(promise: Promise<unknown>): Promise<number> {
  try {
    await promise;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown.status;
    throw thrown;
  }
  throw new Error("expected a refusal, and the call succeeded");
}

describe("bulk delete is the Owner's alone", () => {
  it("refuses an Editor and a Reader before the site is asked anything, and changes nothing", async () => {
    await seed("one", POST("One", "one", "[a]"));
    const before = await rows();
    site.requests.length = 0;
    for (const email of ["editor@test.invalid", "reader@test.invalid"]) {
      const { viewer, project } = await as(email);
      expect(await refusal(bulkApply(env, project, viewer, { op: "delete" }, ["one"], site.fetch))).toBe(403);
      expect(await refusal(deleteFromSite(env, project, viewer, "one", site.fetch))).toBe(403);
    }
    expect(site.requests).toEqual([]);
    expect(site.adapter.store.has("one")).toBe(true);
    expect(await rows()).toEqual(before);
  });

  it("answers the endpoint's JSON 403 for an Editor who posts a delete", async () => {
    await seed("one", POST("One", "one", "[a]"));
    const context = new RouterContextProvider();
    context.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
    context.set(viewerContext, await viewerFor("editor@test.invalid"));
    context.set(nonceContext, "n");
    const body = new FormData();
    body.set("op", "delete");
    body.append("id", "one");
    const response = (await bulkAction({ request: new Request(`https://carrel.test/p/${SLUG}/bulk`, { method: "POST", body }), params: { project: SLUG }, context } as never)) as Response;
    expect(response.status).toBe(403);
    expect(await response.json()).toEqual({ error: "Deleting posts is the Owner's step." });
    expect(site.adapter.store.has("one")).toBe(true);
  });

  it("deletes for the Owner at the version the site holds, records it, drops it from the index and keeps working drafts", async () => {
    await seed("one", POST("One", "one", "[a]"));
    await seed("two", POST("Two", "two", "[a]"));
    const { viewer, project } = await as("owner@test.invalid", "publish");
    await autosave(testEnv.DB, project, viewer, "two", { source: "my unsaved words", baseVersion: null });
    const indexed = () => testEnv.DB.prepare("SELECT COUNT(*) AS n FROM site_items WHERE item_id = 'two'").first<{ n: number }>();
    expect((await indexed())!.n).toBe(1);
    const results = await bulkApply(env, project, viewer, { op: "delete" }, ["one", "two"], site.fetch);
    expect(results.map((r) => [r.id, r.title, r.ok, r.message])).toEqual([
      ["one", "One", true, "Deleted from the site."],
      ["two", "Two", true, "Deleted from the site."],
    ]);
    expect(site.adapter.deletedContent).toEqual(["one", "two"]);
    const log = (await rows()).filter((r) => r.action === "content-delete");
    expect(log).toHaveLength(2);
    expect(log[0]).toMatchObject({ itemId: "one", va: null, who: viewer.id });
    expect(log[0]!.vb).toBeTruthy();
    expect((await indexed())!.n).toBe(0);
    expect((await testEnv.DB.prepare("SELECT source FROM drafts WHERE item_id = 'two'").first<{ source: string }>())?.source).toBe("my unsaved words");
  });
});

describe("a post that cannot be deleted does not stop the others", () => {
  it("reports a missing post, a stale version and a refusal, deletes the rest, and records only what the site did", async () => {
    const adapter = memoryAdapter();
    start(fakeSite(adapter));
    for (const id of ["a", "b", "c", "d"]) await seed(id, POST(id.toUpperCase(), id, "[x]"));
    const real = adapter.content.delete!;
    adapter.content.delete = async (id, input) => {
      if (id === "b") throw new VersionConflictError("someone-else");
      if (id === "c") throw new (await import("@dustinedwards/site-api")).RefusedError("The site keeps this page.");
      return real(id, input);
    };
    const { viewer, project } = await as("owner@test.invalid", "publish");
    const results = await bulkApply(env, project, viewer, { op: "delete" }, ["a", "b", "missing", "c", "d"], site.fetch);
    expect(results.map((r) => [r.id, r.ok])).toEqual([["a", true], ["b", false], ["missing", false], ["c", false], ["d", true]]);
    expect(results.find((r) => r.id === "b")!.message).toMatch(/changed on the site while this ran/);
    expect(results.find((r) => r.id === "missing")!.message).toMatch(/does not have this post|no post with this id/);
    expect(results.find((r) => r.id === "c")!.message).toBe("The site keeps this page.");
    expect(adapter.deletedContent).toEqual(["a", "d"]);
    expect(adapter.store.has("b") && adapter.store.has("c")).toBe(true);
    expect((await rows()).filter((r) => r.action === "content-delete").map((r) => r.itemId)).toEqual(["a", "d"]);
  });

  it("says a site with no delete does not delete, deletes nothing and records nothing", async () => {
    const adapter = memoryAdapter({ contentDelete: false });
    start(fakeSite(adapter));
    await seed("one", POST("One", "one", "[a]"));
    const { viewer, project } = await as("owner@test.invalid", "publish");
    expect(await contentDeleteOffered(env, project, site.fetch)).toEqual({ offered: false, reason: "The site does not delete posts through Carrel yet." });
    const results = await bulkApply(env, project, viewer, { op: "delete" }, ["one"], site.fetch);
    expect(results).toEqual([{ id: "one", title: "one", ok: false, message: "The site does not delete posts through Carrel yet." }]);
    expect(adapter.store.has("one")).toBe(true);
    expect((await rows()).filter((r) => r.action === "content-delete")).toEqual([]);
  });

  it("offers delete where the site has it", async () => {
    const { project } = await as("owner@test.invalid", "publish");
    expect(await contentDeleteOffered(env, project, site.fetch)).toEqual({ offered: true });
  });
});

describe("bulk tag", () => {
  it("changes only the tags line: the rest of the file comes back byte for byte", async () => {
    const original = POST("One", "one", "[alpha, beta]", "A paragraph.\n\nAnother, with *emphasis*.");
    await seed("one", original);
    const { viewer, project } = await as("editor@test.invalid", "edit");
    const [result] = await bulkApply(env, project, viewer, { op: "tag-add", tag: "gamma" }, ["one"], site.fetch);
    expect(result).toMatchObject({ ok: true, message: 'Added the tag "gamma".' });
    expect(sourceOf("one")).toBe(original.replace("tags: [alpha, beta]", "tags: [alpha, beta, gamma]"));
    const [removed] = await bulkApply(env, project, viewer, { op: "tag-remove", tag: "ALPHA" }, ["one"], site.fetch);
    expect(removed).toMatchObject({ ok: true, message: 'Removed the tag "ALPHA".' });
    expect(sourceOf("one")).toBe(original.replace("tags: [alpha, beta]", "tags: [beta, gamma]"));
  });

  it("is a save with its authorship row, and writes nothing for a post that already has the tag", async () => {
    await seed("one", POST("One", "one", "[alpha]"));
    const { viewer, project } = await as("editor@test.invalid", "edit");
    const before = (await rows()).length;
    site.requests.length = 0;
    const [same] = await bulkApply(env, project, viewer, { op: "tag-add", tag: "alpha" }, ["one"], site.fetch);
    expect(same).toMatchObject({ ok: true, message: 'Already tagged "alpha". Not changed.' });
    expect(writes()).toEqual([]);
    expect((await rows()).length).toBe(before);
    await bulkApply(env, project, viewer, { op: "tag-add", tag: "beta" }, ["one"], site.fetch);
    const last = (await rows()).at(-1)!;
    expect(last).toMatchObject({ action: "save", itemId: "one", who: viewer.id });
    expect(last.vb).not.toBe(last.va);
  });

  it("leaves a live post to the Owner: an Editor's tag on it is refused alone, and the others still change", async () => {
    await seed("draft-one", POST("Draft one", "draft-one", "[a]"));
    await seed("live-one", POST("Live one", "live-one", "[a]"), true);
    await seed("draft-two", POST("Draft two", "draft-two", "[a]"));
    const liveBefore = sourceOf("live-one");
    const { viewer, project } = await as("editor@test.invalid", "edit");
    const results = await bulkApply(env, project, viewer, { op: "tag-add", tag: "new" }, ["draft-one", "live-one", "draft-two"], site.fetch);
    expect(results.map((r) => [r.id, r.ok])).toEqual([["draft-one", true], ["live-one", false], ["draft-two", true]]);
    expect(results[1]!.message).toBe("Changing a live post is the Owner's step, so this one was left as it was.");
    expect(results[1]!.title).toBe("Live one");
    expect(sourceOf("live-one")).toBe(liveBefore);
    expect(sourceOf("draft-one")).toContain("tags: [a, new]");
    expect(sourceOf("draft-two")).toContain("tags: [a, new]");
  });

  it("lets the Owner tag a live post", async () => {
    await seed("live-one", POST("Live one", "live-one", "[a]"), true);
    const { viewer, project } = await as("owner@test.invalid", "publish");
    const [result] = await bulkApply(env, project, viewer, { op: "tag-add", tag: "new" }, ["live-one"], site.fetch);
    expect(result!.ok).toBe(true);
    expect(site.adapter.store.get("live-one")!.doc.status).toBe("published");
  });

  it("leaves a post alone when the person has an unsaved working draft of it, so the draft is not lost", async () => {
    await seed("one", POST("One", "one", "[a]"));
    const { viewer, project } = await as("editor@test.invalid", "edit");
    await autosave(testEnv.DB, project, viewer, "one", { source: "half a sentence", baseVersion: null });
    const before = sourceOf("one");
    const [result] = await bulkApply(env, project, viewer, { op: "tag-add", tag: "new" }, ["one"], site.fetch);
    expect(result).toMatchObject({ ok: false });
    expect(result!.message).toMatch(/working draft/);
    expect(sourceOf("one")).toBe(before);
    expect((await testEnv.DB.prepare("SELECT source FROM drafts WHERE item_id = 'one'").first<{ source: string }>())?.source).toBe("half a sentence");
  });

  it("refuses a tag that would break the list, before any post is read", async () => {
    const { viewer, project } = await as("editor@test.invalid", "edit");
    site.requests.length = 0;
    for (const tag of ["", "a, b", "x]", 'say "hi"', "a:b", "x".repeat(41)]) {
      expect(await refusal(bulkApply(env, project, viewer, { op: "tag-add", tag }, ["one"], site.fetch))).toBe(400);
    }
    expect(site.requests).toEqual([]);
    expect(cleanTag("  open source ")).toBe("open source");
  });
});

describe("bulk duplicate", () => {
  it("makes a new draft with an unused id, a copy title and its own slug, created fresh, and leaves the original alone", async () => {
    const original = POST("The original", "orig", "[a, b]", "Words.");
    await seed("orig", original, true);
    const { viewer, project } = await as("editor@test.invalid", "edit");
    const [first] = await bulkApply(env, project, viewer, { op: "duplicate" }, ["orig"], site.fetch);
    expect(first).toMatchObject({ ok: true, copyId: "orig-copy" });
    const [second] = await bulkApply(env, project, viewer, { op: "duplicate" }, ["orig"], site.fetch);
    expect(second).toMatchObject({ ok: true, copyId: "orig-copy-2" });
    expect(sourceOf("orig")).toBe(original);
    expect(sourceOf("orig-copy")).toBe(original.replace('title: "The original"', 'title: "The original (copy)"').replace("slug: orig", "slug: orig-copy"));
    expect(sourceOf("orig-copy-2")).toContain('title: "The original (copy 2)"');
    expect(site.adapter.store.get("orig-copy")!.doc.status).toBe("draft");
    const created = (await rows()).filter((r) => r.itemId === "orig-copy");
    expect(created).toHaveLength(1);
    expect(created[0]).toMatchObject({ action: "save", vb: null, who: viewer.id });
  });

  it("sets draft: true on a copy of a live post, and adds the key when the post lacks one", async () => {
    await seed("live", POST("Live", "live", "[a]").replace("draft: true", "draft: false"), true);
    await seed("bare", "---\ntitle: Bare\n---\n\nBody.\n");
    const { viewer, project } = await as("editor@test.invalid", "edit");
    await bulkApply(env, project, viewer, { op: "duplicate" }, ["live", "bare"], site.fetch);
    expect(sourceOf("live-copy")).toContain("draft: true");
    expect(sourceOf("live-copy")).not.toContain("draft: false");
    expect(sourceOf("bare-copy")).toBe("---\ntitle: \"Bare (copy)\"\ndraft: true\n---\n\nBody.\n");
  });

  it("skips an id that a working draft or an AI draft already uses, and one the site already holds", async () => {
    await seed("orig", POST("Orig", "orig", "[a]"));
    await seed("orig-copy", POST("Taken on the site", "orig-copy", "[a]"));
    const { viewer, project } = await as("editor@test.invalid", "edit");
    await autosave(testEnv.DB, project, viewer, "orig-copy-2", { source: "a draft only in Carrel", baseVersion: null });
    const [result] = await bulkApply(env, project, viewer, { op: "duplicate" }, ["orig"], site.fetch);
    expect(result).toMatchObject({ ok: true, copyId: "orig-copy-3" });
  });

  it("reports a post the site does not have and one with no frontmatter, and copies the rest", async () => {
    await seed("plain", "No frontmatter here.\n");
    await seed("good", POST("Good", "good", "[a]"));
    const { viewer, project } = await as("editor@test.invalid", "edit");
    const results = await bulkApply(env, project, viewer, { op: "duplicate" }, ["ghost", "plain", "good"], site.fetch);
    expect(results.map((r) => [r.id, r.ok])).toEqual([["ghost", false], ["plain", false], ["good", true]]);
    expect(results[1]!.message).toMatch(/no frontmatter/);
    expect(site.adapter.store.has("plain-copy")).toBe(false);
  });
});

describe("what a request may carry", () => {
  it("refuses a Reader, nothing chosen and too many posts, and never sends an id that could not be one", async () => {
    const reader = await as("reader@test.invalid");
    expect(await refusal(bulkApply(env, reader.project, reader.viewer, { op: "duplicate" }, ["one"], site.fetch))).toBe(403);
    const { viewer, project } = await as("editor@test.invalid", "edit");
    expect(await refusal(bulkApply(env, project, viewer, { op: "duplicate" }, [], site.fetch))).toBe(400);
    expect(await refusal(bulkApply(env, project, viewer, { op: "duplicate" }, Array.from({ length: MAX_BULK + 1 }, (_, i) => `p-${i}`), site.fetch))).toBe(400);
    site.requests.length = 0;
    const results = await bulkApply(env, project, viewer, { op: "duplicate" }, ["../etc", "a b"], site.fetch);
    expect(results.every((r) => !r.ok && /not a post id/.test(r.message))).toBe(true);
    expect(site.requests).toEqual([]);
  });
});

