// The Google routes through their loaders: manuscripts and Connect Google are the Owner's, and the
// OAuth round trip runs through the real route with the fake Google behind it.

import { RouterContextProvider } from "react-router";
import { beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { clearSaTokenCache } from "~/lib/google/service-account.server";
import { loader as authLoader } from "~/routes/auth.google";
import { loader as homeLoader } from "~/routes/home";
import { loader as manuscriptsLoader } from "~/routes/manuscripts";

import { addPerson, resetDb, testEnv } from "./env";
import { CODE, fakeGoogle, serviceAccountKey } from "./google";
import { viewerFor } from "./site";

let key: Awaited<ReturnType<typeof serviceAccountKey>>;
beforeAll(async () => {
  key = await serviceAccountKey();
});

let env: Env;
beforeEach(async () => {
  clearSaTokenCache();
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  await addPerson("editor@test.invalid");
  vi.stubGlobal("fetch", fakeGoogle({ publicJwk: key.publicJwk }).fetch);
  env = {
    ...testEnv,
    GOOGLE_SA_KEY: key.json,
    GOOGLE_OAUTH_CLIENT_ID: "id",
    GOOGLE_OAUTH_CLIENT_SECRET: "secret",
    GOOGLE_TOKEN_KEY: btoa(String.fromCharCode(...new Uint8Array(32).fill(7))),
    GOOGLE_MANUSCRIPTS_FOLDER_ID: "folderRoot1",
  } as Env;
});

async function context(email: string) {
  const c = new RouterContextProvider();
  c.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  c.set(viewerContext, await viewerFor(email));
  c.set(nonceContext, "n");
  return c;
}

async function settle<T>(p: Promise<T>): Promise<T | Response> {
  try {
    return await p;
  } catch (thrown) {
    if (thrown instanceof Response) return thrown;
    throw thrown;
  }
}

describe("Google routes", () => {
  it("PLANT: manuscripts and Connect Google are 404 to anyone but the Owner", async () => {
    const req = new Request("https://carrel.test/manuscripts");
    expect(((await settle(manuscriptsLoader({ request: req, params: {}, context: await context("editor@test.invalid") } as never))) as Response).status).toBe(404);
    const start = new Request("https://carrel.test/auth/google/start");
    expect(((await settle(authLoader({ request: start, params: { step: "start" }, context: await context("editor@test.invalid") } as never))) as Response).status).toBe(404);
    const home = (await homeLoader({ request: new Request("https://carrel.test/"), params: {}, context: await context("editor@test.invalid") } as never)) as Awaited<ReturnType<typeof homeLoader>>;
    expect(home.google).toBeNull();
  });

  it("connects Google through the real routes and says so on the home page", async () => {
    const owner = await context("owner@test.invalid");
    const start = (await authLoader({ request: new Request("https://carrel.test/auth/google/start"), params: { step: "start" }, context: owner } as never)) as Response;
    const google = new URL(start.headers.get("Location")!);
    expect(google.hostname).toBe("accounts.google.com");
    const back = new Request(`https://carrel.test/auth/google/callback?state=${google.searchParams.get("state")}&code=${encodeURIComponent(CODE)}`);
    const done = (await authLoader({ request: back, params: { step: "callback" }, context: await context("owner@test.invalid") } as never)) as Response;
    const message = new URL(done.headers.get("Location")!, "https://carrel.test").searchParams.get("google");
    expect(message).toBe("Google is connected for Send to Docs and Import (drive.file only).");
    const home = (await homeLoader({ request: new Request("https://carrel.test/"), params: {}, context: await context("owner@test.invalid") } as never)) as Awaited<ReturnType<typeof homeLoader>>;
    expect(home.google).toEqual({ configured: true, connected: true });
  });

  it("shows the manuscripts page with the setup still missing, rather than failing", async () => {
    env = { ...env, GOOGLE_SA_KEY: undefined } as Env;
    const data = (await manuscriptsLoader({ request: new Request("https://carrel.test/manuscripts?q=x"), params: {}, context: await context("owner@test.invalid") } as never)) as Awaited<
      ReturnType<typeof manuscriptsLoader>
    >;
    expect(data.setup).toMatch(/^GOOGLE_SA_KEY is not set/);
    expect(data.files).toEqual([]);
  });
});

test/editor-ux.test.ts.source:
// The editor and AI draft screens' behaviour behind the UX pass: "Use as my draft" writes the
// person's working copy in Carrel and nothing to the site, the AI draft's rendered view is private
// to its owner, and the save line says a draft on the site is not live.

import { RouterContextProvider } from "react-router";
import { beforeEach, describe, expect, it, vi } from "vitest";

import { saveAiDraft } from "~/lib/ai.server";
import { readDraft } from "~/lib/content.server";
import { cloudflareContext, nonceContext, viewerContext } from "~/lib/context";
import { requireSiteProject } from "~/lib/projects.server";
import { siteState } from "~/lib/save-state";
import { action as aiDraftAction } from "~/routes/ai-draft";
import { loader as aiPreviewLoader } from "~/routes/ai-draft.preview";

import { addPerson, addProject, resetDb, share } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const SLUG = "de-info";
const THEIR_SOURCE = "---\ntitle: The AI's take\nunknown_key: kept\n---\nAn alternative opening.\n";
let site: ReturnType<typeof fakeSite>;
let env: Env;

beforeEach(async () => {
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  const editor = await addPerson("editor@test.invalid");
  const id = await addProject(SLUG, "dustinedwards");
  await share(id, editor, "editor");
  site = fakeSite();
  vi.stubGlobal("fetch", site.fetch);
  env = connectedEnv();
});

async function context(email: string) {
  const c = new RouterContextProvider();
  c.set(cloudflareContext, { env, ctx: {} as ExecutionContext });
  c.set(viewerContext, await viewerFor(email));
  c.set(nonceContext, "n");
  return c;
}

async function aiDraftFor(email: string, item: string) {
  const viewer = await viewerFor(email);
  const project = await requireSiteProject(env.DB, viewer, SLUG, "edit");
  const { id } = await saveAiDraft(env, project, { viewer, client: "Claude" }, item, { source: THEIR_SOURCE });
  return { id, viewer, project };
}

describe("Use as my draft", () => {
  it("writes the working copy in Carrel exactly as the AI wrote it, and sends nothing to the site", async () => {
    const saved = await site.adapter.content.saveDraft("post-one", { source: "---\ntitle: Site copy\n---\nOn the site.\n", expectedVersion: null, changeId: "s" });
    const { id, viewer, project } = await aiDraftFor("owner@test.invalid", "post-one");
    const before = site.requests.length;

    const result = await aiDraftAction({ params: { project: SLUG, item: "post-one", id: String(id) }, request: new Request("https://carrel.test/", { method: "POST" }), context: await context("owner@test.invalid") } as never);
    expect((result as Response).status).toBe(302);

    expect(await readDraft(env.DB, project, viewer, "post-one")).toMatchObject({ source: THEIR_SOURCE });
    expect(site.requests.slice(before).filter((r) => !r.startsWith("GET "))).toEqual([]);
    const onSite = await site.adapter.content.get("post-one");
    expect(onSite?.version).toBe(saved.version);
    expect(onSite?.source).toContain("On the site.");
  });
});

describe("the AI draft's rendered view", () => {
  it("renders the draft through the site for its owner", async () => {
    const { id } = await aiDraftFor("owner@test.invalid", "post-one");
    const response = (await aiPreviewLoader({ params: { project: SLUG, item: "post-one", id: String(id) }, context: await context("owner@test.invalid") } as never)) as Response;
    expect(response.status).toBe(200);
    expect(response.headers.get("Content-Security-Policy")).toMatch(/^sandbox; default-src 'none'/);
    expect(await response.text()).toContain("The AI's take");
  });

  it("PLANT: is never shown to another person, whose request answers 404", async () => {
    const { id } = await aiDraftFor("owner@test.invalid", "post-one");
    await expect(aiPreviewLoader({ params: { project: SLUG, item: "post-one", id: String(id) }, context: await context("editor@test.invalid") } as never)).rejects.toMatchObject({ status: 404 });
  });
});

describe("the save line", () => {
  it("does not read as live for a draft on the site", () => {
    expect(siteState("draft", false)).toBe("Saved as a draft on the site. Not published yet.");
    expect(siteState("draft", true)).toBe("Matches the site's draft. It is not live.");
    expect(siteState("scheduled", true)).toMatch(/scheduled/);
    expect(siteState("published", true)).toBe("Matches the live post");
  });
});

test/social.test.ts.source:
// The social queue (design decision 5) against fake Bluesky, X and routine endpoints. Planted: a reply
// attempt refused; a post failing the lint held; the template used only after the routine fails; the
// health email when a template post goes out. Nothing here reaches a real platform.

import { beforeEach, describe, expect, it } from "vitest";

import { writeToSite } from "~/lib/content.server";
import { runHealth } from "~/lib/health.server";
import { requireSiteProject } from "~/lib/projects.server";
import { lintPost } from "~/lib/social/lint";
import { assertOriginalPost, clearBlueskySessions, oauthSignature, percentEncode, SocialRefused } from "~/lib/social/platforms.server";
import {
  BATCH_DELAY_MS,
  createAccount,
  decidePost,
  draftSocialPost,
  processSocial,
  recordPublication,
  ROUTINE_WAIT_MS,
  setSwitches,
  socialOverview,
} from "~/lib/social/queue.server";

import { addPerson, addProject, resetDb, testEnv } from "./env";
import { connectedEnv, fakeSite, viewerFor } from "./site";

const ROUTINE_URL = "https://api.anthropic.com/v1/claude_code/routines/trig_01TEST/fire";

type Sent = { url: string; body: Record<string, unknown>; auth: string | null };

/** Bluesky, X and the routine trigger, answering as the real ones do. */
function fakeWorld(routineStatus: number | (() => number) = 200) {
  const sent: Sent[] = [];
  const fires: { text: string; headers: Record<string, string> }[] = [];
  const fetch = (async (input: RequestInfo | URL, init?: RequestInit) => {
    const request = new Request(input, init);
    const body = (await request.json().catch(() => ({}))) as Record<string, unknown>;
    if (request.url === ROUTINE_URL) {
      fires.push({ text: String(body.text ?? ""), headers: Object.fromEntries(request.headers) });
      const status = typeof routineStatus === "function" ? routineStatus() : routineStatus;
      if (status !== 200) return Response.json({ type: "error", error: { type: status === 429 ? "rate_limit_error" : "authentication_error", message: "no" } }, { status });
      return Response.json({ type: "routine_fire", claude_code_session_id: "session_01", claude_code_session_url: "https://claude.ai/code/session_01" });
    }
    sent.push({ url: request.url, body, auth: request.headers.get("Authorization") });
    if (request.url.endsWith("createSession")) return Response.json({ accessJwt: "jwt", did: "did:plc:test" });
    if (request.url.endsWith("createRecord")) return Response.json({ uri: `at://did:plc:test/app.bsky.feed.post/${sent.length}` });
    if (request.url === "https://api.x.com/2/tweets") return Response.json({ data: { id: `x${sent.length}`, text: body.text } });
    throw new Error(`the tests reach only the fakes, not ${request.url}`);
  }) as typeof globalThis.fetch;
  return { fetch, sent, fires };
}

let projectId: number;
let env: Env;
const NOW = new Date("2026-09-27T15:00:00Z");
const later = (ms: number) => new Date(NOW.getTime() + ms);

function mailbox() {
  const sent: { subject: string; text: string }[] = [];
  return { sent, EMAIL: { send: async (m: { subject: string; text: string }) => (sent.push(m), { messageId: "m" }) } as unknown as SendEmail };
}

async function owner() {
  return viewerFor("owner@test.invalid");
}

async function account(key: string, opts: { platform?: "bluesky" | "x"; kind?: "brand" | "personal"; mode?: "auto" | "approval"; budget?: number } = {}) {
  const o = await owner();
  const created = await createAccount(testEnv.DB, o, { key, name: key, platform: opts.platform ?? "bluesky", kind: opts.kind ?? "brand", handle: `${key}.bsky.social`, projectId });
  if (!created.ok) throw new Error(created.error);
  const row = await testEnv.DB.prepare("SELECT id FROM social_accounts WHERE key = ?").bind(key).first<{ id: number }>();
  await setSwitches(testEnv.DB, o, row!.id, { enabled: true, mode: opts.mode ?? "auto", monthlyBudgetMills: opts.budget ?? 0 });
  return row!.id;
}

async function posts() {
  return (await socialOverview(testEnv.DB, await owner())).posts.map((p) => ({ ...p.post, accountKey: p.accountKey }));
}

const PIECE = { id: "post-one", title: "Stromatolites of the Paluxy", url: "https://site.test/blog/post-one", summary: "What the river keeps." };

beforeEach(async () => {
  clearBlueskySessions();
  await resetDb();
  await addPerson("owner@test.invalid", { owner: true });
  projectId = await addProject("germomics", "dustinedwards");
  env = {
    ...connectedEnv(),
    SOCIAL_ROUTINE_URL: ROUTINE_URL,
    SOCIAL_ROUTINE_TOKEN: "sk-ant-oat01-test",
    SOCIAL_GERMOMICS_BLUESKY_BLUESKY_APP_PASSWORD: "app-pass",
    SOCIAL_FOXING_BLUESKY_BLUESKY_APP_PASSWORD: "app-pass-2",
    SOCIAL_DUSTIN_X_X_API_KEY: "k",
    SOCIAL_DUSTIN_X_X_API_SECRET: "s",
    SOCIAL_DUSTIN_X_X_ACCESS_TOKEN: "t",
    SOCIAL_DUSTIN_X_X_ACCESS_SECRET: "ts",
  } as Env;
});

describe("PLANT: a reply attempt is refused, before anything is sent", () => {
  it("refuses a Bluesky record with a reply, a follow, a like, and any other endpoint", () => {
    const bsky = "https://bsky.social/xrpc/com.atproto.repo.createRecord";
    const reply = { uri: "at://x", cid: "y" };
    expect(() => assertOriginalPost("POST", bsky, { repo: "d", collection: "app.bsky.feed.post", record: { $type: "app.bsky.feed.post", text: "hi", reply: { root: reply, parent: reply } } })).toThrow(SocialRefused);
    expect(() => assertOriginalPost("POST", bsky, { repo: "d", collection: "app.bsky.graph.follow", record: { $type: "app.bsky.graph.follow" } })).toThrow(SocialRefused);
    expect(() => assertOriginalPost("POST", bsky, { repo: "d", collection: "app.bsky.feed.like", record: { $type: "app.bsky.feed.like" } })).toThrow(SocialRefused);
    expect(() => assertOriginalPost("POST", "https://api.bsky.chat/xrpc/chat.bsky.convo.sendMessage", {})).toThrow(SocialRefused);
    expect(() => assertOriginalPost("GET", "https://bsky.social/xrpc/app.bsky.feed.searchPosts?q=x", undefined)).toThrow(SocialRefused);
  });

  it("refuses an X post that replies or quotes, and any other X endpoint", () => {
    expect(() => assertOriginalPost("POST", "https://api.x.com/2/tweets", { text: "hi", reply: { in_reply_to_tweet_id: "1" } })).toThrow(SocialRefused);
    expect(() => assertOriginalPost("POST", "https://api.x.com/2/tweets", { text: "hi", quote_tweet_id: "1" })).toThrow(SocialRefused);
    expect(() => assertOriginalPost("POST", "https://api.x.com/2/dm_conversations/with/1/messages", { text: "hi" })).toThrow(SocialRefused);
  });

  it("lets an original post through", () => {
    expect(() => assertOriginalPost("POST", "https://api.x.com/2/tweets", { text: "hi" })).not.toThrow();
    expect(() => assertOriginalPost("POST", "https://bsky.social/xrpc/com.atproto.repo.createRecord", { repo: "d", collection: "app.bsky.feed.post", record: { $type: "app.bsky.feed.post", text: "hi" } })).not.toThrow();
  });
});

